UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "role": "Pesquisador Sênior", "area": "Engenharia Agrícola com ênfase em Sensoriamento Remoto", "competency": "Domínio de Tecnologias de Sensoriamento Remoto e SIG", "definition": "Alta capacidade técnica na operação de Sistemas de Informação Geográfica (SIG) e no processamento de imagens e dados obtidos por sensores remotos.", "description": "Aplicação de tecnologias aeroespaciais (como imagens de satélite e sensores) para analisar, mapear e gerenciar dinâmicas no campo."}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "role": "Coordenador do Eixo 1", "area": "Agricultura de Precisão e Digital", "competency": "Planejamento Territorial e Ambiental", "definition": "Competência para cruzar dados de infraestrutura (sua base em Engenharia de Transportes) com dados biofísicos para planejar o uso da terra e a conservação ambiental.", "description": "Monitoramento detalhado das lavouras para identificar a variabilidade do solo e das plantas, permitindo o manejo focado e inteligente da produção."}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "role": "Coordenador do Eixo 1", "area": "Geoprocessamento e Análise Espacial", "competency": "Análise de Variabilidade Espacial e Temporal", "definition": "Habilidade em identificar padrões, mudanças e variações ao longo do tempo no campo, essencial para prever safras e mitigar riscos climáticos ou de manejo.", "description": "Uso de sistemas computacionais para integrar dados geográficos e agrícolas, voltados ao planejamento territorial e à gestão do meio ambiente."}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "role": "Coordenador do Eixo 1", "area": "Previsão de Safra e Monitoramento Agrícola", "competency": "Pesquisa Científica e Tecnológica Aplicada ao Agronegócio e à Sustentabilidade", "definition": "Sólida experiência como pesquisador da Unicamp, traduzindo conceitos complexos de engenharia em soluções práticas para o agronegócio e a sustentabilidade.", "description": "Desenvolvimento de modelos para estimar a produtividade de culturas e acompanhar o desenvolvimento agrícola em tempo real."}]}, {"id": "projetos", "items": [{"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O Centro Paulista de Estudos em Biogás (CP2B) promove o uso inteligente de resíduos para sustentabilidade, desenvolvendo soluções inovadoras de biogás. O CP2B busca conhecimento e articula ações para aproveitar o grande potencial de biogás em São Paulo, especialmente nos setores sucroenergético e urbano (RSU e esgoto). O centro pesquisa bioprodutos, atua em oito eixos temáticos e opera como laboratório vivo, testando soluções com a sociedade.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "title": "Ferramentas geo-espaciais para monitorar utilização de plásticos na agricultura para fins de reciclagem", "description": "Projeto constituído de duas partes. Uma parte é identificar onde está o plástico utilizado na agricultura, e outra é desenvolver uma ferramenta que ajude na logística de retirada deste material do campo. A primeira parte foi desenvolvida utilizando séries temporais de imagens de satélite e inteligência artificial. Na segunda parte, foi proposta uma ferramenta baseada em SIG com a ajuda do método AHP para localizar os melhores lugares para construção de recicladoras.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "title": "Centro de Engenharia na Plasticultura", "description": "Criação de um centro de pesquisa com foco em plasticultura sob a chamada Fapesp- Braskem.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "title": "SmartPest-Ghana: Exploring LLM-driven mobile solutions for climate-smart pest management in maize farming", "description": "A Parceria entre as Universidades Sheffield (UK) Unicamp/NIPE (Brasil) Ghana, a Empresa Mutus-Tech (Inovação- UK), foi contemplada com um fundo de Inovação do UKRI (United Kingdom Business Connect) para desenvolver um projeto de Inovação chamado SmartPest-Ghana: Exploring LLM-driven mobile solutions for climate-smart pest management in maize farming, iniciativa liderada pelo Prof. Dr. Po Yang da Universidade de Sheffield. A iniciativa é para atender pequenos produtores em Gana com respeito a minimização de um problema sério que os produtores enfrentam com o ataque da lagarta-do-cartucho.", "period": "2025 – 2026", "trl": null, "partners": null}, {"person": "Rubens Augusto Camargo Lamparelli", "institution": "NIPE/UNICAMP", "title": "Mapeamento de Áreas Disponíveis no Brasil Visando uma Futura Implantação de uma Planta de Produção de Microalgas / Cianobactérias com Geração de Valor", "description": "O objetivo geral deste projeto é identificar locais prioritários no Brasil para a construção de sistemas de produção de microalgas e cianobactérias para geração de valor associadas às fontes emissoras de CO2.A identificação se dará pelo levantamento de Informações referentes aos aspectos geográficos (clima, radiação solar), fontes estacionárias de emissões de CO2 (refinarias, termelétricas, UPGN-Unidade de Processamento de Gás Natural, usinas de açúcar e álcool, cimenteiras, siderúrgicas dentre outras) os quais estarão inseridos num Sistema de Informações Geográficas (SIG).O SIG permite a análise espacial entre as variáveis possibilitando a identificação das áreas propicias que serão mostradas na forma de Heatmaps. Informações de caráter sócio econômico e ambiental também serão levantadas.", "period": "2025 – atual", "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Leonardo Ariel Benavidez Mamani", "institution": "UNICAMP", "level": "Doutorando", "title": "Análise da sinergia em usinas de diferente porte para a geração de biogás aproveitando o glicerol cru como subproduto de biodiesel. Estudo de Caso Município de El Alto – Bolívia", "area": "Planejamento de Sistemas Energéticos"}, {"person": "Lucas Nakamura Cerejo", "institution": "NIPE/UNICAMP", "level": "Pós-Doc", "title": "Democratizing Biogas Assessment: An Open-Source Web Platform Integrating Satellite Imagery and Government Databases for Regional Energy Planning in São Paulo State, Brazil", "area": "Planejamento Energético e Biogás"}]}]'::jsonb WHERE axis_number = 1;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "role": "Professor USP", "area": "Ciências Ambientais e Engenharia Civil/Sanitária", "competency": "Especialidade no Tratamento e Valorização de Vinhaça", "definition": "Domínio técnico sobre o principal efluente da produção de etanol (a vinhaça), focando em reduzir seu poder poluente e extrair seu potencial econômico.", "description": "Atuação voltada ao tratamento de efluentes, gestão de resíduos e mitigação de impactos ambientais causados por atividades industriais."}, {"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "role": "Coordenador Eixo 2", "area": "Recuperação e Balanço Energético", "competency": "Processos de Digestão Anaeróbia", "definition": "Profundo conhecimento prático e teórico na operação de reatores biológicos que decompõem a matéria orgânica na ausência de oxigênio, uma tecnologia chave para o saneamento e a produção de biogás.", "description": "Avaliação e planejamento do aproveitamento de subprodutos industriais para transformá-los em fontes limpas de energia, calculando a eficiência e viabilidade do sistema."}, {"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "role": "Coordenador Eixo 2", "area": "Bioenergia e Geração de Metano", "competency": "Cálculo e Análise de Balanço Energético", "definition": "Capacidade de mensurar e comparar a quantidade de energia gasta em um processo versus a quantidade de energia recuperada, garantindo que os projetos de bioenergia sejam eficientes e sustentáveis.", "description": "Foco no desenvolvimento e otimização de rotas biológicas para a produção de biocombustíveis gasosos a partir de biomassa e resíduos orgânicos."}, {"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "role": "Coordenador Eixo 2", "area": null, "competency": "Formação Acadêmica Multidisciplinar Avançada", "definition": "Visão integrada que une os conceitos práticos da Engenharia Ambiental (UNESP), a base de recursos naturais e geológicos da Geologia (UNESP), e o rigor metodológico e estrutural da Engenharia Civil (USP).", "description": null}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "role": "Professora USP", "area": "Planejamento e Desenvolvimento Energético", "competency": "Operação e Coordenação de Usinas Termoelétricas a Biogás", "definition": "Capacidade prática comprovada na gestão operacional e supervisão técnica de plantas industriais de geração de energia elétrica a partir de biogás.", "description": "Atuação acadêmica e de pesquisa focada em integrar fontes de energia renováveis e tecnologias sustentáveis à matriz energética (atualmente no IEE-USP)."}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "role": "Coordenadora Adjunta do Eixo 2", "area": "Biotecnologia Ambiental e Saneamento", "competency": "Desenvolvimento de Reatores Anaeróbios e Processos Biotecnológicos", "definition": "Profundo domínio técnico no projeto e na condução de sistemas biológicos de degradação de matéria orgânica (ausência de oxigênio) voltados para a produção de metano.", "description": "Desenvolvimento de soluções biológicas para o tratamento de resíduos agroindustriais, mitigação de impactos ambientais e saneamento."}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "role": "Coordenadora Adjunta do Eixo 2", "area": "Engenharia de Processos e Operação de Usinas", "competency": "Recuperação de Nutrientes e Economia Circular", "definition": "Habilidade para desenhar e operar processos que, além de gerar energia, recuperam nutrientes valiosos dos resíduos agroindustriais, fechando ciclos produtivos sustentáveis.", "description": "Atuação técnica e industrial voltada ao monitoramento, controle e otimização de instalações de conversão energética em grande escala."}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "role": "Coordenadora Adjunta do Eixo 2", "area": "Bioenergia (Biogás e Biometano)", "competency": "Pesquisa Aplicada e Escalonamento Industrial (Scale-up)", "definition": "Competência para transitar da teoria científica para a prática, demonstrada no desenvolvimento de pesquisas em plantas industriais e de demonstração instaladas na USP.", "description": "Foco na cadeia completa de produção desses biocombustíveis, desde a escala de laboratório até a demonstração e aplicação em escala industrial."}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "role": "Coordenadora Adjunta do Eixo 2", "area": null, "competency": "Formação Internacional e Visão Interdisciplinar em Engenharia, Saneamento e Recursos Naturais", "definition": "Sólida bagagem acadêmica com duplo doutorado (USP no Brasil e Universidad de La Frontera no Chile), unindo as bases da Engenharia Ambiental, Engenharia Hidráulica, Saneamento e Recursos Naturais.", "description": null}]}, {"id": "projetos", "items": [{"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos é dedicado ao tema \"Aproveitamento inteligente de resíduos para o desenvolvimento sustentável\" e visa criar competências com base em ciência que conduzam ao desenvolvimento e aplicações de soluções inovadoras de biogás. Os sistemas energéticos sociotécnicos que incluem soluções de biogás têm um desempenho de sustentabilidade bastante positivo uma vez que tratam resíduos, produzem combustível renovável e criam nutrientes renováveis para as plantas. No Estado de São Paulo (ESP) há muito substrato disponível - um potencial de mais de 4,5 bilhões de m3 ano de biogás - assim como uma grande demanda por seus bioprodutos, mas apenas uma fração deste potencial é aproveitada. O papel do CP2B é criar novos conhecimentos e competências que levem a soluções aplicáveis ao biogás no Estado, e articular ações conjuntas nas esferas industrial, política, social e ambiental. O CP2B tem por principal objetivo contribuir para a gestão de resíduos orgânicos e lignocelulósicos - urbanos e agroindustriais -, com prioridade para as ações voltadas à gestão pública de resíduos em setores estratégicos para a economia do estado. Em 2022, o setor sucroenergético injetou mais de R$50 bilhões na economia do estado, que responde por 50 da produção nacional de cana, por 44 do etanol e 60 de açúcar (safra 2023/24). O potencial de produção de biogás neste setor representa mais de 50 do potencial nacional, sendo que a integração com outros setores por meio de ecopólos ou ecoparques deve resultar em soluções sustentáveis e inovadoras. Nosso grupo de pesquisa tem avaliado a potencial integração de resíduos para produção de biogás. No segmento urbano, a produção de biogás a partir de RSU e esgoto sanitário representa muito mais do que uma oportunidade econômica: contribui para questões de saúde pública. Os RSU ainda são dispostos em aterros sanitários, a maioria deles sem sistema para coleta de biogás. Onde existe, a não-segregação compromete a eficiência do sistema de produção de biogás. Portanto, é necessário buscar soluções inovadoras e ações integradas da Ciência, com o poder público, com a sociedade e com o setor empresarial. Tais soluções devem ir além da geração do biogás e do digestato, inerentes aos sistemas de biogás tradicionais, abrindo um novo horizonte para pesquisas acerca do potencial de outros bioprodutos, o que permitirá agregar ainda mais valor aos resíduos. O centro irá atuar de forma transdisciplinar. O foco está em fornecer conhecimento, competência, colaboração aprofundada entre disciplinas científicas e com profissionais, novas soluções e análises da contribuição para uma transição de sustentabilidade aos stakeholders ao longo da cadeia de valor, ao setor de biogás e às comunidades em geral. Comunicação, networking, educação e capacitação são ferramentas para alcançar a visão, estratégia e objetivos do centro de concretizar o potencial de sustentabilidade e inovação das soluções de biogás. Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados: 1 - Inventário de Resíduos e Mapeamento de Tecnologias; 2 - Ciência e Tecnologia de Base (Coordenador: Lucas Tadeu Fuess); 3 - Engenharia de Processos e Bioprocessos; 4 - Avaliação Integrada Socioeconômica, Ambiental e Energética; 5 - Inovação em Bioprodutos na Cadeia do Biogás; 6 - Educação e Capacitação para o Desenvolvimento Sustentável; 7 - Difusão Científica e Comunicação; 8 - Políticas Públicas e Inovação Regulatória. Por fim, o CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva. (AU).", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "title": "Centro de Ciências para o Desenvolvimento em Energias do Futuro - CENF", "description": "Esta proposta trata da criação de um Centro de Ciências para o Desenvolvimento em Energias Renováveis e Combustíveis do Futuro em conjunto com a Secretaria de Meio Ambiente, Infraestrutura e Logística (SEMIL), por meio de sua Subsecretaria de Energia e Mineração (SEM), para enfrentar os desafios atuais relacionados à descarbonização da indústria e do setor de transporte paulista de forma economicamente viável e ambientalmente adequada. Em específico, este centro buscará soluções para implementação do Hidrogênio de baixa intensidade de carbono com as seguintes verticais de pesquisa: (i) Produção, (ii) Armazenamento e Transporte, (iii) Usos e Aplicações e (iv) Regulamentação, de modo a buscar o protagonismo do Estado de São Paulo no desenvolvimento de tecnologias avançadas e na promoção da indústria nacional. Para endereçar a complexidade destes assuntos, a formação de uma rede de parcerias é essencial e, nesta proposta, se unem ao IPT a Escola Politécnica da USP, UFSCAR, UFPR, UFABC, o ISI de Eletroquímica e a Associação Brasileira de Energia Eólica (ABEEólica), para garantir o alinhamento estratégicos dos temas abordados com as necessidades da indústria. Esse alinhamento permitirá o desenvolvimento da cadeia de fornecedores nacional para componentes relacionados ao uso de H2 como fonte de energia. As instituições participaram ativamente da estruturação dos temas a serem desenvolvidos no CCD-ERCF, incluindo a definição das metas e a contrapartida econômica. Considerando a sustentabilidade do Centro, foram concebidos planos de parcerias e comunicação que permitirão o desenvolvimento futuro de novas linhas de pesquisa e a incorporação de novas empresas, estreitando os laços com diferentes setores da indústria e promovendo a transferência das tecnologias, se tornando um centro de conexões (Hub) para o uso de Hidrogênio como combustível do futuro e ações de divulgação para diferentes públicos. É importante ressaltar empresas de diferentes setores econômicos apresentaram interesse e forneceram cartas de apoio a fundação do CCD-ERCF, vislumbrando participação colaborativa em futuros projetos. (AU).", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Lucas Tadeu Fuess", "institution": "Engenharia Ambiental/USP", "title": "Consolidação do conceito de biorrefinaria aplicado ao tratamento biológico de águas residuárias e de resíduos sólidos (Temático FAPESP - 22/10615-1)", "description": "O conceito de biorrefinaria tem sido aplicado a sistemas de tratamento de águas residuárias e de resíduos sólidos por vários grupos de pesquisa em todo o mundo. Muitos avanços têm sido obtidos principalmente com a aplicação da biotecnologia anaeróbia, com rendimentos e produtividades crescentes na produção de ácidos orgânicos, solventes, bioplásticos, hidrogênio e metano, entre outros produtos de interesse. O domínio crescente dos conceitos básicos associados ao processo global tem levado a propostas diversificadas para valoração dos despejos e resíduos predominantemente orgânicos. Os grupos associados para o desenvolvimento deste projeto trabalham conjuntamente há mais de uma década, sempre com foco nos fundamentos dos processos e, com esta proposta, buscam a consolidação deste conhecimento acumulado para testar a hipótese de que é possível a aplicação e consolidação do conceito de biorrefinaria ao processamento de águas residuárias e resíduos sólidos pela aplicação de tecnologia anaeróbia, aliada a processos físico-químicos e catalíticos. O objetivo geral do projeto temático é aprofundar o conhecimento sobre a aplicação de tecnologia anaeróbia, como unidade principal ou combinada com processos físico-químicos e com processos químicos catalíticos, para o processamento de águas residuárias e resíduos sólidos, subprodutos de processos industriais, para consolidação do conceito de biorrefinaria. Para isso, os grupos trabalharão de forma integrada para: (i) aplicar diferentes processos de transformação e de reatores anaeróbios, no tratamento de subprodutos e águas residuárias da agroindústria, com a finalidade de geração de bioenergia e obtenção de produtos de elevado valor agregado; (ii) valorar resíduos lignocelulósicos dentro do conceito de biorrefinaria por meio de codigestão, integração da liquefação hidrotérmica e digestão anaeróbia e conversão direta de derivados da biomassa lignocelulósica utilizando catalisadores heterogêneos bifuncionais; (iii) desenvolver e investigar catalisadores à base de metais não-nobres para a conversão direta de CH4 e CO2 a ácido acético e para a conversão de CH4 e CO2 a gás de síntese via DRM (dry reforming of methane); (iv) desenvolver modelos matemáticos para os processos anaeróbios presentes em biorrefinarias; (v) aplicar a metodologia de Análise de Ciclo de Vida (ACV) para a determinação do desempenho ambiental da biorrefinaria. Com isso, espera-se que a visão tradicional do saneamento seja superada, para que se consolide definitivamente a visão de recuperação de energia e materiais para a adequação ambiental dos efluentes e resíduos gerados.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "title": "Valorização de digestato produzido em usinas de biogás da USP e da UFC no cultivo convencional e hidropônico: avaliação da produção sustentável no cultivo de cana, milho e hortaliças", "description": "O número de usinas de biogás cresceu de 113 em 2015 para 755 em 2021, atingindo uma produção total de 2,3 bilhões Nm3 de biogás por ano, utilizado para geração de energia elétrica (71), térmica (6) ou biometano (23). Além do aproveitamento do fluxo de energia dos resíduos e efluentes, plantas de biogás permitem a recuperação do conteúdo de nutrientes, um produto de alto valor para condicionamento de solos e fertilização agrícola. Somente 5 das plantas atuais de biogás usam o digestato como fertilizante. O uso do disgetado no setor agrícola permite fechar os ciclos de nutrientes e diminuir a dependência da agricultura brasileira da importação desses insumos. Além de nutrientes inorgânicos, o digestato contém grande quantidade de microrganismos representando uma comunidade extremamente biodiversa e é rico em compostos orgânicos metabolizáveis na faixa aeróbia dos solos. Há carência de estudos para geração de produtos de alto valor agregado a partir do digestato, em escalas econômicas. Os processos de produção do disgestato, serão estudados simultaneamente no IEE-USP e na UFC, enquanto as pesquisas para compreensão do impacto do uso do digestato em diferentes solos e culturas, serão desenvolvidos no IEE-USP na UFC e na Apta Centro Sul, considerando as potencialidades locais. O projeto terá por objetivos: (i) avaliar o balanço de nutrientes em usinas de biogás de escalas semi-industrial e piloto, (ii) desenvolver e avaliar técnicas de tratamento, recuperação, produção e enriquecimento de biofertilizante a partir do digestato; (iii) avaliar o impacto do uso dos biofertilizante produzidos em diferentes tipos de cultivo: vaso, hidroponia e cultivo extensivo, inclusive em ambiente urbano; (iv) avaliar o impacto ambiental das técnicas estudadas e o valor agregado dos produtos para a produção de alimentos no Brasil; (v) avaliar o estado-da-arte do uso de biofertilizante no Brasil e as barreiras regulatórias e institucionais para sua difusão.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Priscila Rosseto Camiloti", "institution": "Divisão Científica de Planejamento, Análise e Desenvolvimento Energético do Instituto de Energia e Ambiente/USP", "title": "não tem CP2B no Lattes", "description": null, "period": null, "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Alexandre Da Silva Souza", "institution": "UNIFAL", "level": "Doutorando", "title": "Desenvolvimento de sistema de co-digestão de resíduo sólido orgânico e esgoto sanitário para geração de biogás", "area": "Saneamento Ambiental e Tratamento de Efluentes"}, {"person": "Antonio Eduardo Colins Sena", "institution": null, "level": "Graduando", "title": "Estudo da influência da viscosidade sobre a digestão anaeróbia de resíduos de alimento em duas etapas", "area": "Ciência e Engenharia de Alimentos"}, {"person": "Denis da Silva Miranda", "institution": "NIPE/UNICAMP", "level": "Doutorando", "title": "Aproveitamento energético de resíduos sólidos urbanos e construção de modelos de gestão para a produção de biogás em sistemas de duas etapas", "area": "Engenharia Química e Bioenergia"}, {"person": "Eder Kevin Arango Escalante", "institution": "UNICAMP", "level": "Mestrando", "title": "POA/PRAV", "area": "Ciências Ambientais e Gestão de Recursos Naturais"}, {"person": "Jessica Cristina Franco Nogueira", "institution": "UNIFAL", "level": "Doutoranda", "title": "Integração de subprodutos do setor sucroalcooleiro e da pecuária para a recuperação energética do biogás e a produção de biofertilizantes em reator do tipo CSTR", "area": "Planejamento de Sistemas Energéticos"}, {"person": "Luiza Arones Gaspar", "institution": null, "level": "Graduanda", "title": "INTEGRACÃO CANA-DE-ACÚCAR E PECUÁRIA: AVALIACÃO DO POTENCIAL BIOQUÍMICO DE METANO", "area": "Educação e Pedagogia"}, {"person": "Marcelo Zaiat", "institution": null, "level": "Professor", "title": null, "area": "Tratamento Biológico de Águas Residuárias"}, {"person": "Marcus Lívio Carlin", "institution": "UNIFAL", "level": "Mestre", "title": "EFEITOS DA SAZONALIDADE CLIMÁTICA E DA DIETA NO POTENCIAL BIOQUÍMICO DE METANO DE DEJETOS DE VACAS VACAS LACTANTES E NÃO LACTANTES", "area": "Agronomia (com ênfase em Cafeicultura)"}, {"person": "Simone Aparecida dos Santos", "institution": "NIPE/UNICAMP", "level": "Doutoranda", "title": "Avaliação do Consórcio Microbiano de Reatores Anaeróbios Tratando da vinhaça Frente a Aplicação de Diferentes Condições Operacionais Objetivando Otimizar O Rendimento da Produção de Biogás", "area": "Planejamento de Sistemas Energéticos"}, {"person": "Stella Stopa Assis Palma", "institution": "NIPE/UNICAMP", "level": "Pós-Doc", "title": "BIOINSUMOS E BIOFERTILIZANTES, COM APROVEITAMENTO DE RESÍDUOS AGROPECUÁRIOS E URBANOS PARA INSUMOS, ENERGIA, BIOGÁS, BIOMETANO E AMÔNIA VERDE", "area": "Engenharia Agrícola (Principal)"}]}, {"id": "infra", "items": [{"acronym": "CEMARA (UNIFAL)", "name": "CEMARA", "institution": "UNIFAL", "lead": "Renata P. Rodriguez", "trl": "TRL 2 e TRL 4"}, {"acronym": "CP2b Lab", "name": "CP2b Lab", "institution": "NIPE/UNICAMP", "lead": "Bruna de Souza Moraes", "trl": "O TRL médio desta estrutura fica concentrado entre TRL 3 e TRL 5, com o \"centro de gravidade\" no TRL 4."}]}]'::jsonb WHERE axis_number = 2;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "role": "Professora UNICAMP", "area": "Engenharia Sanitária e de Águas Residuais", "competency": "Remoção Biológica de Nutrientes e Processos Avançados (como o Anammox)", "definition": "Domínio técnico na eliminação de poluentes complexos (como nitrogênio e fósforo) por vias biológicas. Sua experiência internacional no renomado instituto IHE Delft (Holanda) chancela sua especialidade no processo Anammox (uma tecnologia biológica altamente eficiente para a remoção de nitrogênio).", "description": "Foco no projeto, análise e aprimoramento de sistemas de coleta, afastamento e tratamento de efluentes domésticos e industriais."}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "role": "Coordenadora Eixo 3", "area": "Sistemas de Tratamento Centralizados", "competency": "Recuperação de Recursos em Saneamento", "definition": "Capacidade de enxergar o esgoto não apenas como um resíduo, mas como fonte de recursos, desenvolvendo pesquisas para extrair água de reuso, nutrientes ou energia do processo de tratamento.", "description": "Atuação em grandes plantas de tratamento urbanas, focando no refino dos processos para torná-los mais eficientes e sustentáveis."}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "role": "Coordenadora Eixo 3", "area": "Sistemas de Tratamento Descentralizados", "competency": "Livre-Docência e Ensino Superior em Engenharia", "definition": "Reconhecida capacidade didática e acadêmica consolidada pelo título de Livre-Docente na UNICAMP, habilitando-a como liderança no ensino e na formação de novos engenheiros na área de sistemas de coleta e tratamento.", "description": "Desenvolvimento e aplicação de tecnologias adaptadas para pequenas comunidades, áreas rurais e regiões isoladas, promovendo a universalização do saneamento de forma viável."}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "role": "Coordenadora Eixo 3", "area": null, "competency": "Formação Multidisciplinar e Integrada em Saneamento", "definition": "Sólida base de conhecimento construída desde a formação tecnológica e de engenharia até o doutorado, o que lhe confere uma visão prática e profunda sobre a gestão ambiental e o saneamento básico.", "description": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "role": "Professor UNICAMP", "area": "Química Sanitária e Ambiental", "competency": "Otimização de Metodologias Analíticas e Análise de Metais-Traço", "definition": "Alta capacidade técnica para criar, validar e aprimorar métodos químicos capazes de detectar e quantificar substâncias e metais poluentes em quantidades minúsculas (traços) em amostras ambientais e sanitárias.", "description": "Aplicação dos conceitos e ferramentas da química para entender, monitorar e solucionar problemas relacionados ao saneamento, qualidade da água e conservação ambiental."}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "role": "Coordenador Adjunto do Eixo 3", "area": "Ciências Ambientais e Tecnologia", "competency": "Cromatografia e Espectrometria de Massas de Alta Resolução", "definition": "Domínio no uso de equipamentos analíticos sofisticados para identificar com precisão a presença de contaminantes emergentes (como fármacos e pesticidas) e seus produtos de transformação no meio ambiente.", "description": "Atuação no ensino superior e na pós-graduação (FT-UNICAMP), desenvolvendo pesquisas voltadas a processos tecnológicos sustentáveis e à gestão ambiental."}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "role": "Coordenador Adjunto do Eixo 3", "area": "Gestão e Coordenação Acadêmico-Científica", "competency": "Processos Oxidativos e Redutivos Avançados (POA/PRAv)", "definition": "Especialidade em tecnologias avançadas de tratamento químico capazes de degradar e destruir poluentes altamente persistentes que os tratamentos biológicos convencionais não conseguem eliminar.", "description": "Liderança institucional demonstrada na coordenação de programas de pós-graduação (PPGT), na gestão de grupos de pesquisa (GOTAS) e na coordenação adjunta de eixos em centros de excelência (CP2B)."}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "role": "Coordenador Adjunto do Eixo 3", "area": "Gerenciamento de Resíduos Institucionais", "competency": "Pesquisa Internacional e Liderança de Redes Científicas", "definition": "Bagagem consolidada por pós-doutorado em um centro europeu de referência (IDAEA/CSIC, na Espanha) e papel ativo como membro fundador de associações científicas nacionais (como a ABPOA).", "description": "Desenvolvimento de estratégias e práticas para o manejo, tratamento e descarte correto de resíduos gerados dentro de universidades e institutos de pesquisa."}]}, {"id": "projetos", "items": [{"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos (CP2B)", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos (CP2B) tem como foco o aproveitamento inteligente de resíduos para o desenvolvimento sustentável, promovendo soluções inovadoras de biogás com base científica, integrando dimensões industriais, políticas, sociais e ambientais. Atuando de forma transdisciplinar, o CP2B busca transformar o potencial subutilizado de biogás no Estado de São Paulo estimado em mais de 4,5 bilhões de m por ano em valor econômico, ambiental e social, especialmente nos setores urbano e sucroenergético. Seu objetivo é fortalecer a gestão de resíduos orgânicos e lignocelulósicos, impulsionar a produção de biogás e seus bioprodutos, e fomentar ecoparques e sinergias entre setores estratégicos, contribuindo também para a saúde pública e a transição sustentável. Para isso, organiza suas ações em oito eixos temáticos integrados, desde mapeamento de resíduos e tecnologias até políticas públicas e inovação regulatória, atuando como um laboratório vivo que conecta ciência, sociedade e setor produtivo.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Desenvolvimento de bioproduto a base de Alginato (alginate-like exopolysaccharides) extraído de Lodo Granular Aeróbio para aplicações industriais", "description": "Estações de tratamento de esgoto passaram do conceito de remoção de poluentes para recuperação de recursos e se enquadraram no contexto da economia circular. Neste sentido, a tecnologia de Lodo Granular Aeróbio (LGA) tem sido importante pois os microrganismos produzem substâncias poliméricas extracelulares (EPS) que podem ser recuperadas, reduzindo o volume de lodo final a ser disposto e o custo de seu transporte. Um dos constituintes do EPA é o alginate-like exopolysaccharides (ALE) que tem potencial para aplicações industriais, porém suas características são influenciadas pelas condições operacionais dos reatores de onde o LGA é removido para sua extração, e de condições climáticas. Assim, é importante verificar se condições tropicais influenciam na formação do ALE e no desempenho para aplicações industriais. Com isso, o objetivo deste trabalho tem como base o estudo das extrações de ALE do LGA removido de reatores operados em escala real em clima tropical para verificar se há influência na quantidade e na qualidade de ALE extraídos. Também será verificado o seu desempenho em duas aplicações industriais: (i) cura do cimento e (ii) adsorção no tratamento de águas. Ainda será realizado o cálculo das emissões veiculares geradas nas rotas necessárias para o transporte do subproduto produzido a seus potenciais consumidores finais.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Influência do descarte intencional na estabilidade do lodo granular aeróbio e da eficiência de remoção de fósforo em reatores de batelada sequencial", "description": "Este estudo investiga como diferentes estratégias de descarte intencional de lodo granular aeróbio (LGA), seletivo e não seletivo, influenciam a estabilidade do lodo e a eficiência de remoção biológica de fósforo em reatores de batelada sequencial (RBS). A tecnologia com LGA, como o Nereda, dispensa decantadores secundários, dificultando o controle da idade do lodo. Modificações no descarte podem afetar a microbiologia do sistema e favorecer organismos acumuladores de fósforo (PAOs). Serão utilizados três RBS em escala piloto para comparar o desempenho sob distintas condições operacionais. O objetivo é otimizar o tratamento de efluentes e mitigar a eutrofização dos corpos hídricos.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "CEUCI - Centro de Estudos sobre Urbanização para o Conhecimento e a Inovação: áreas do conhecimento em franjas urbanas: diretrizes de implantação sustentável com o apoio da modelagem da informação", "description": "No atual contexto de sociedade do conhecimento, espera-se que diversos campi universitários das cidades paulistas venham a passar por um processo de transformação nas próximas décadas, com a instalação, em seu entorno, de institutos de pesquisa e desenvolvimento, hubs de inovação e empresas de base tecnológica. Essas novas áreas urbanas do conhecimento demandarão uma série de equipamentos e infraestruturas, tais como habitação, serviços, saneamento, espaços livres de uso público, dentre outros. Tendo em vista sua localização, tipicamente em áreas de franja urbana, na interface com áreas agrícolas, fragmentos de matas naturais e outras preexistências geralmente desconexas das áreas urbanas consolidadas, e pelo atual cenário de mudanças climáticas, de destruição dos ecossistemas e de crise econômico-social, essa transformação enfrentará diversos desafios, exigindo novos métodos e ferramentas de planejamento urbano. Alinhado com os Objetivos do Desenvolvimento Sustentável, o presente projeto de pesquisa se propõe a estudar essas questões, por meio dos seguintes eixos temáticos transversais: tecnologias, governança, políticas públicas, legislação urbanística, economia circular/donut, mitigação da gentrificação e paradigma ecológico. O projeto dá continuidade aos trabalhos iniciados em 2020 com a criação de um programa de pós-graduação lato sensu na FECFAU destinado a estudar a implementação do Hub para o Desenvolvimento Sustentável (HIDS), no qual o campus de Barão Geraldo da Unicamp está inserido. Os procedimentos metodológicos incluirão, nos primeiros três anos de projeto, revisões sistemáticas da literatura, estudos de caso, observação participante do desenvolvimento do projeto para o HIDS, o processo participativo com as comunidades envolvidas e oficinas de discussão de conceitos com grupos focais. Como resultados, serão produzidos quadros conceituais sobre a criação de novas áreas urbanas do conhecimento, contribuindo para o desenvolvimento econômico, social, ambiental e urbano. Na segunda fase do projeto, esse processo metodológico será aplicado experimentalmente a outras cidades do estado de São Paulo e será proposto um novo programa interdisciplinar de pós-graduação interunidades na Unicamp, institucionalizando uma nova linha de pesquisa sobre o tema.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Laboratório Ambiental Online: Monitoramento do Desempenho de Estações de Tratamento de Águas Residuais", "description": "Recurso para gravação de aulas online sobre análises laboratoriais para desenvolver um curso de extensão de difusão.", "period": "2024 – 2025", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Condições de saneamento básico de áreas alagáveis: Estudo de caso em Igapó Açu", "description": "Melhoria nas condições de saneamento básico de áreas alagáveis: Estudo de caso em Igapó Açu.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Formação continuada para a universalização do saneamento: O que podemos aprender com os operadores?", "description": "Entrevistas com operadores de Estações de Tratamento de Esgoto (ETE) para identificar lacunas do conhecimento e de processos de aprendizagem. Será formatado um curso de acordo com as observações e características observadas nas conversas com os operadores.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Programa de Extensão SeR Saneamento e Recuperação de Recursos", "description": "Este programa visa elaborar e executar projetos na área de sanemento e recuperação de recursos coletivamente e de forma dialógica junto com a comunidade externa a Universidade.Os projetos envolvem desde planejamento, escolha, construção, operação e monitoramento de sistemas de tratamento de águas residuais até a criação e multiplicação de conteúdo de educação ambiental.O incentivo e fomento às atividades abordadas neste programa são essenciais para promover o avanço no setor de saneamento. O estreitamento da universidade com as comunidades traz demandas sociais e são um caminho significativamente importante para que dificuldades básicas sejam superadas não somente localmente mas em outras regiões do Brasil.Para a universidade, o programa tem o potencial de auxiliar na remodelagem da forma e do conteúdo de ensino universitário, uma vez que propicia o contato dos professores e estudantes com demandas diretas de comunidades que hoje pouco interagem com a Unicamp. O programa preza, neste sentido, pela interação ensino pesquisa extensão.Nessa perspectiva, o programa pode contribuir com a popularização da universidade, redirecionando a produção científica universitária para demandas mais imediatamente ligadas aos interesses das comunidades atuantes na área de saneamento.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Explorando o Ribeirão Quilombo: Sensibilização Ambiental e Monitoramento pela Escola Telêmaco", "description": "Atividade de educação ambiental na escola municipal Telêmaco em Campinas. Projeto inserido no Programa de Olhos no Futuro da Unicamp.", "period": "2023 – 2025", "trl": null, "partners": null}, {"person": "Luana Mattos de Oliveira Cruz", "institution": "FEC/UNICAMP", "title": "Programa UniversIDADE: Consumo Responsável, Reciclagem e Compostagem", "description": "Curso de extensão sobre a temática Consumo Responsável, Reciclagem e Compostagem para idosos. Curso inserido no Programa de Extensão da Unicamp chamado UniversIDADE.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B (FAPESP 2024/01112-1)", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos é dedicado ao tema \"Aproveitamento inteligente de resíduos para o desenvolvimento sustentável\" e visa criar competências com base em ciência que conduzam ao desenvolvimento e aplicações de soluções inovadoras de biogás. Os sistemas energéticos sociotécnicos que incluem soluções de biogás têm um desempenho de sustentabilidade bastante positivo uma vez que tratam resíduos, produzem combustível renovável e criam nutrientes renováveis para as plantas. No Estado de São Paulo (ESP) há muito substrato disponível - um potencial de mais de 4,5 bilhões de m3 ano de biogás - assim como uma grande demanda por seus bioprodutos, mas apenas uma fração deste potencial é aproveitada. O papel do CP2B é criar novos conhecimentos e competências que levem a soluções aplicáveis ao biogás no Estado, e articular ações conjuntas nas esferas industrial, política, social e ambiental. O CP2B tem por principal objetivo contribuir para a gestão de resíduos orgânicos e lignocelulósicos - urbanos e agroindustriais -, com prioridade para as ações voltadas à gestão pública de resíduos em setores estratégicos para a economia do estado.Em 2022, o setor sucroenergético injetou mais de R$50 bilhões na economia do estado, que responde por 50 da produção nacional de cana, por 44 do etanol e 60 de açúcar (safra 2023/24). O potencial de produção de biogás neste setor representa mais de 50 do potencial nacional, sendo que a integração com outros setores por meio de ecopólos ou ecoparques deve resultar em soluções sustentáveis e inovadoras. Nosso grupo de pesquisa tem avaliado a potencial integração de resíduos para produção de biogás. No segmento urbano, a produção de biogás a partir de RSU e esgoto sanitário representa muito mais do que uma oportunidade econômica: contribui para questões de saúde pública. Os RSU ainda são dispostos em aterros sanitários, a maioria deles sem sistema para coleta de biogás. Onde existe, a não-segregação compromete a eficiência do sistema de produção de biogás. Portanto, é necessário buscar soluções inovadoras e ações integradas da Ciência, como poder público, com a sociedade e com o setor empresarial. Tais soluções devem ir além da geração do biogás e do digestato, inerentes aos sistemas de biogás tradicionais, abrindo um novo horizonte para pesquisas acerca do potencial de outros bioprodutos, o que permitirá agregar ainda mais valor aos resíduos. O centro irá atuar de forma transdisciplinar. O foco está em fornecer conhecimento, competência,colaboração aprofundada entre disciplinas científicas e com profissionais, novas soluções e análises da contribuição para uma transição de sustentabilidade aos stakeholders ao longo da cadeia de valor, ao setor de biogás e às comunidades em geral. Comunicação, networking, educação e capacitação são ferramentas para alcançar a visão, estratégia e objetivos do centro de concretizar o potencial de sustentabilidade e inovação das soluções de biogás. Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados: 1 - Inventário de Resíduos e Mapeamento de Tecnologias; 2 - Ciência e Tecnologia de Base; 3 - Engenharia de Processos e Bioprocessos; 4 - Avaliação Integrada Socioeconômica, Ambiental e Energética; 5 - Inovação em Bioprodutos na Cadeia do Biogás; 6 - Educação e Capacitação para o Desenvolvimento Sustentável; 7 - Difusão Científica e Comunicação; 8 - Políticas Públicas e Inovação Regulatória. Por fim, o CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "title": "Processos oxidativos e redutivos avançados fotomediados, aplicados à transformação de contaminantes emergentes presentes em águas em geral", "description": "Alternativas aos processos convencionais de tratamento de efluentes estão sendo elaboradas, baseadas em processos redutivos e oxidativos avançados, ativados por luz.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "title": "Novas tecnologias de tratmento de águas para fins de reuso - aquisição de espectrofotômetro UV-vis capaz de realizar varreduras espectrais", "description": "Referente ao Edital PESQ/FT nº 01/2022 - Apoio a novos projetos de pesquisa.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "title": "Desenvolvimento de método multibarreira para o tratamento de efluentes para reuso", "description": "Projeto de cooperação internacional entre CAPES (Brasil) e COFECUB (França), envolvendo pesquisadores de ambos os países e alunos brasileiros.", "period": "2019 – atual", "trl": null, "partners": null}, {"person": "Enelton Fagnani", "institution": "Ciências Ambientais/FT/UNICAMP", "title": "Removal of emerging contaminants during disinfection of urban wastewater by advanced oxidation", "description": "Este projeto visa estabelecer uma cooperação científica entre a Universidade de Campinas e a Universidade de Barcelona através dos grupos de pesquisa envolvidos. O grupo brasileiro tem um Projeto Jovem Pesquisador (JP) dedicado à desinfecção de águas residuais urbanas e reutilização de efluentes, enquanto o foco do grupo espanhol estuda a remoção de contaminantes emergentes e tecnologias de oxidação avançada. Acreditamos que essa cooperação irá aumentar as chances de sucesso do projeto JP no Brasil devido à vasta experiência e equipamentos que o grupo de pesquisa espanhol possui. Um dos objetivos específicos do projeto JP é verificar a remoção de alguns contaminantes industriais, tais como aditivos e detergentes (nonilfenol e ftalatos). Com essa colaboração será possível estender essa pesquisa para verificar a remoção de outros compostos chamados contaminantes emergentes (CE). Esses compostos começam a ser legislados na Europa e EUA, após inúmeros projetos de pesquisa terem identificados compostos que podem ser usados como indicadores de remoção dos EC. Entre estes contaminantes podemos citar produtos farmacêuticos, pesticidas, hormônios e produtos para cuidados pessoais. O 17a-etinilestradiol, benzotriazol, diclofenaco, mecoprope, sulfametoxazol e terbutrin foram os compostos escolhidos para ser objeto desta pesquisa complementar.", "period": "2017 – atual", "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Amanda Pietra Santerio Cavini", "institution": "UNIFAL", "level": "Mestre", "title": "Utilização de residuos agroindustriais para produção de biogás.", "area": "Farmácia Industrial e Tecnologia Farmacêutica"}, {"person": "Gabriel de Oliveira Rodrigues", "institution": "USP", "level": "Doutorando", "title": "Sustainable Biogas Purification with Ionic Liquid-Modified Sewage Sludge Char", "area": "Transição Energética e Economia Circular"}, {"person": "Henrique de Souza Dornelles", "institution": "UNICAMP", "level": "Pós-Doc", "title": "Aplicação de ferramentas meta-ômicas em digestão anaeróbia.", "area": "Saneamento e Engenharia Hidráulica"}, {"person": "Jessica Jacinta Silva", "institution": "UNIFAL", "level": "Doutoranda", "title": "Pré tratamento de resíduos lignocelulosicos", "area": "Ciências da Engenharia Ambiental e Bioenergia"}, {"person": "Patricia Prediger", "institution": "FT UNICAMP", "level": "Professora", "title": "Separação de gases por membranas", "area": "Química Ambiental e Tratamento de Águas"}, {"person": "Paulo Sergio Graziano Magalhães", "institution": "UNICAMP", "level": "Professor", "title": "Aproveitamento de resíduos", "area": "Engenharia Agrícola e Mecanização"}]}, {"id": "infra", "items": [{"acronym": "CP2b Lab", "name": "CP2b Lab", "institution": "NIPE/UNICAMP", "lead": "Bruna de Souza Moraes", "trl": "O TRL médio desta estrutura fica concentrado entre TRL 3 e TRL 5, com o \"centro de gravidade\" no TRL 4."}, {"acronym": "PPBIOEN", "name": "Planta Piloto para Bioenergia", "institution": "NIPE/UNICAMP", "lead": "Bruna de Souza Moraes", "trl": "TRL 4 e TRL 6."}]}]'::jsonb WHERE axis_number = 3;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "role": "Professor UNICAMP", "area": "Economia da Energia e Planejamento Energético", "competency": "Modelagem de Insumo-Produto e Equilíbrio Geral Computável (EGC)", "definition": "Alta capacidade técnica para construir e operar modelos econômicos complexos. Essas ferramentas servem para simular e prever os impactos socioeconômicos e ambientais que ocorrem quando há mudanças tecnológicas, reformas na estrutura econômica ou a inserção de novos setores produtivos.", "description": "Estudo e análise de setores energéticos, avaliando a viabilidade, a transição e as dinâmicas de mercado ligadas à produção e ao consumo de energia."}, {"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "role": "Coordenador NIPE", "area": "Economia Agrícola e do Meio Ambiente", "competency": "Avaliação Qualitativa e Quantitativa de Sustentabilidade", "definition": "Competência para liderar a análise de indicadores de sustentabilidade em projetos de grande escala, integrando dados econômicos, sociais e ecológicos para dar suporte a tomadas de decisão.", "description": "Análise das relações entre a produção do campo, o uso de recursos naturais e as políticas econômicas voltadas à sustentabilidade e à mitigação de impactos ambientais."}, {"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "role": "Coordenador do Eixo 4", "area": "Economia Matemática e de Empresas", "competency": "Formação Interdisciplinar Avançada em Engenharia e Matemática", "definition": "Domínio de ferramentas de áreas distintas e complementares, unindo o rigor analítico da Engenharia Mecânica (USP) e da Matemática Aplicada (Unicamp) com a visão estratégica do Planejamento Energético e da Economia.", "description": "Aplicação de ferramentas matemáticas e estatísticas rigorosas para compreender o comportamento de mercados, estruturas corporativas e políticas macroeconômicas."}, {"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "role": "Coordenador do Eixo 4", "area": "Gestão e Planejamento Estratégico Institucional", "competency": "Articulação Internacional e Pesquisa de Ponta", "definition": "Experiência acadêmica global consolidada por sua atuação como professor visitante no prestigiado Centre of Policy Studies (CoPS) na Austrália, um dos principais centros do mundo em modelagem de equilíbrio geral.", "description": "Atuação na administração universitária de alto nível (Unicamp) e na coordenação de grandes projetos estratégicos voltados ao desenvolvimento sustentável global (como o HIDS)."}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "role": "Professor ITA", "area": "Economia da Energia e Biocombustíveis", "competency": "Modelagem Econômica e Econometria", "definition": "Domínio na aplicação de métodos matemáticos e estatísticos complexos para analisar dados reais, testar teorias e projetar cenários para o mercado de energia e recursos naturais.", "description": "Realização de pesquisas aplicadas sobre o mercado e a viabilidade econômica da transição energética, englobando biogás, bioprodutos, biodiesel, combustíveis avançados e rotas de etanol (1ª geração, 2ª geração e milho)."}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "role": "Coordenador Adjunto do Eixo 4", "area": "Ensino Superior em Engenharia de Elite", "competency": "Ciência de Dados (Data Science Analytics)", "definition": "Competência técnica para minerar, processar e interpretar grandes volumes de dados (Big Data), transformando informações brutas em inteligência para a tomada de decisão.", "description": "Docência voltada à formação de engenheiros de energia e de sistemas no ITA (campus Fortaleza) e atuação na pós-graduação stricto sensu focada em bioenergia e inovação (Unicamp e USP)."}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "role": "Coordenador Adjunto do Eixo 4", "area": "Avaliação Integrada de Impactos", "competency": "Gestão Financeira, Controladoria e Governança", "definition": "Capacidade de gerenciar o planejamento financeiro e a saúde fiscal de instituições, consolidada por sua experiência como Diretor Financeiro de incubadora e conselheiro fiscal da SBE.", "description": "Liderança em análises que conectam aspectos socioeconômicos, ambientais e energéticos de novas tecnologias, atuando como Coordenador Adjunto no Centro Paulista de Estudos em Biogás e Bioprodutos (CP2B)."}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "role": "Coordenador Adjunto do Eixo 4", "area": "Economia da Inovação e Ecossistema Empreendedor", "competency": "Cientometria", "definition": "Habilidade analítica para mapear e quantificar o avanço do conhecimento científico e do desenvolvimento tecnológico de setores industriais.", "description": "Atuação estratégica voltada à gestão de incubadoras de empresas tecnológicas e governança corporativa de associações ligadas ao setor de bioenergia."}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "role": "Coordenador Adjunto do Eixo 4", "area": null, "competency": "Articulação Institucional entre os Setores Civil e Militar", "definition": "Forte trânsito e habilidade de liderança para coordenar projetos e lecionar em algumas das instituições de maior prestígio do país, como o ITA, a AFA, a USP e a Unicamp.", "description": null}]}, {"id": "projetos", "items": [{"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "title": "Integração de modelos econômicos para apoio à decisão em políticas de alocação de águas", "description": "Diante da crescente competição entre os usos da água, transferências crescentes de água são possibilitados através de projetos de interligação entre bacias (PIB), que são planejados, construídos e avaliados como solução para a escassez hídrica dentro da estratégia conhecida como ?gestão de oferta?. Esta solução, senão adequadamente gerida pode não evitar situações de escassez futura, especialmente diante de mudanças climáticas, bem como levar a conflitos sociais e impactos ambientais e econômicos não desejados. Nossa proposta se concentra em uma abordagem complementar aos investimentos em infraestrutura realizados na gestão da oferta - a chamada gestão de demanda - que explora soluções que promovam a flexibilidade e adaptabilidade necessárias diante do crescente estresse e incerteza na disponibilidade hídrica e necessidade de transferências crescentes de água entre bacias. Nosso estudo foca no uso da Economia (ou da ?Economia da Gestão de Recursos Hídricos?) no processo decisório de estabelecimento de estratégias de alocação de águas, levando em conta quantidade e qualidade do recurso, que instrumentalizem uma gestão sustentável de bacias hidrográficas e suas interligações. Pretende-se ampliar o conhecimento e a efetiva aplicação de modelos hidro-econômicos, bem como analisar as possíveis soluções para acoplamento da modelagem em nível de bacia com modelos econômicos agregados tais como modelos de Input-Output e de Equilíbrio Geral. O estudo de caso proposto será a interligação das bacias dos rios Capibaribe, Ipojuca e Una no Estado de Pernambuco através da adutora do Agreste, que receberá águas do eixo leste do projeto de Transposição do rio São Francisco (PTSF) através do Ramal do Agreste. A Adutora constitui-se na maior obra hídrica em construção do Estado, que ainda assim possui, segundo recente levantamento feito pela Agência Nacional de Águas (ANA) em 2015, dois terços dos seus municípios carentes de novos investimentos em infraestrutura. Essas obras de engenharia hídrica viabilizam e regularizam o suprimento do recurso, temporal e espacialmente, e constituem-se na já mencionada estratégia de gestão de oferta, extremamente necessária em Pernambuco, mas não suficiente.", "period": "2018 – atual", "trl": null, "partners": null}, {"person": "Marcelo Pereira Cunha", "institution": "Economia/UNICAMP", "title": "não tem CP2B no Lattes", "description": null, "period": null, "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos é dedicado ao tema \"Aproveitamento inteligente de resíduos para o desenvolvimento sustentável\" e visa criar competências com base em ciência que conduzam ao desenvolvimento e aplicações de soluções inovadoras de biogás. Os sistemas energéticos sociotécnicos que incluem soluções de biogás têm um desempenho de sustentabilidade bastante positivo uma vez que tratam resíduos, produzem combustível renovável e criam nutrientes renováveis para as plantas. No Estado de São Paulo (ESP) há muito substrato disponível - um potencial de mais de 4,5 bilhões de m3 ano de biogás - assim como uma grande demanda por seus bioprodutos, mas apenas uma fração deste potencial é aproveitada. O papel do CP2B é criar novos conhecimentos e competências que levem a soluções aplicáveis ao biogás no Estado, e articular ações conjuntas nas esferas industrial, política, social e ambiental. O CP2B tem por principal objetivo contribuir para a gestão de resíduos orgânicos e lignocelulósicos - urbanos e agroindustriais -, com prioridade para as ações voltadas à gestão pública de resíduos em setores estratégicos para a economia do estado. Em 2022, o setor sucroenergético injetou mais de R$50 bilhões na economia do estado, que responde por 50 da produção nacional de cana, por 44 do etanol e 60 de açúcar (safra 2023/24). O potencial de produção de biogás neste setor representa mais de 50 do potencial nacional, sendo que a integração com outros setores por meio de ecopólos ou ecoparques deve resultar em soluções sustentáveis e inovadoras. Nosso grupo de pesquisa tem avaliado a potencial integração de resíduos para produção de biogás. No segmento urbano, a produção de biogás a partir de RSU e esgoto sanitário representa muito mais do que uma oportunidade econômica: contribui para questões de saúde pública. Os RSU ainda são dispostos em aterros sanitários, a maioria deles sem sistema para coleta de biogás. Onde existe, a não-segregação compromete a eficiência do sistema de produção de biogás. Portanto, é necessário buscar soluções inovadoras e ações integradas da Ciência, com o poder público, com a sociedade e com o setor empresarial. Tais soluções devem ir além da geração do biogás e do digestato, inerentes aos sistemas de biogás tradicionais, abrindo um novo horizonte para pesquisas acerca do potencial de outros bioprodutos, o que permitirá agregar ainda mais valor aos resíduos. O centro irá atuar de forma transdisciplinar. O foco está em fornecer conhecimento, competência, colaboração aprofundada entre disciplinas científicas e com profissionais, novas soluções e análises da contribuição para uma transição de sustentabilidade aos stakeholders ao longo da cadeia de valor, ao setor de biogás e às comunidades em geral. Comunicação, networking, educação e capacitação são ferramentas para alcançar a visão, estratégia e objetivos do centro de concretizar o potencial de sustentabilidade e inovação das soluções de biogás. Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados: 1 - Inventário de Resíduos e Mapeamento de Tecnologias; 2 - Ciência e Tecnologia de Base; 3 - Engenharia de Processos e Bioprocessos; 4 - Avaliação Integrada Socioeconômica, Ambiental e Energética; 5 - Inovação em Bioprodutos na Cadeia do Biogás; 6 - Educação e Capacitação para o Desenvolvimento Sustentável; 7 - Difusão Científica e Comunicação; 8 - Políticas Públicas e Inovação Regulatória. Por fim, o CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "RENOVABIO: UMA ANÁLISE DAS NOTAS DE EFICIÊNCIA, DA CONCESSÃO DE CRÉDITO E DO CUSTO DA DÍVIDA", "description": "O RenovaBio corresponde à Política Nacional de Biocombustível, visando reduzir a intensidade de carbono da matriz de combustíveis em 10 até 2030, garantindo a sustentabilidade da produção de biocombustíveis e a redução das emissões de GEE. Há uma literatura que avalia a eficácia de programas voltados para a redução dos gases causadores do efeito estufa, indicando se houve ou não diminuição na intensidade de carbono (IC) do combustível. Neste sentido, busca-se comparar a participação dos produtores de biocombustível no RenovaBio, dada pela nota de eficiência, em relação aos seus pares, para avaliar se, a região, as certificações, as firmas inspetoras, o tamanho, o desempenho financeiro e o endividamento são elementos que podem influenciar a intensidade de carbono, e, consequentemente, a nota de eficiência. Ademais, busca-se investigar os determinantes de financiamento privado e público em programas voltados para transição energética de baixo carbono, destacando o papel do governo em incentivar os credores a facilitar o financiamento ao setor de energia renovável. Por fim, há literatura sobre a associação entre intensidade de carbono e custo de capital, indicando que os credores podem exigir uma taxa de juros menor para casos de baixa emissão de GEE, o que representa um incentivo para avaliar a relação entre a nota de eficiência e custo de capital de terceiros dos produtores. Diante disso, o objetivo da pesquisa é compreender os direcionadores das notas de eficiência, da concessão de crédito e do custo da dívida das empresas que participam do RenovaBio. O método compreende modelos econométricos, questionários e entrevistas, sendo que os dados coletados correspondem ao período de 2020, 2021 e 2022.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "Mitigação dos efeitos das mudanças climáticas e as perspectivas para o agronegócio brasileiro", "description": "Os efeitos negativos das mudanças climáticas podem ser visualizados nas sucessivas perdas econômicas na agricultura e pecuária mundial nas últimas duas décadas. Não obstante, as previsões para as próximas décadas envolvem graus de mitigação, isto é, não há consenso entre os países qual será o grau adotado de forma assertiva. Tal fato por si só gera incerteza, tornando complexa a previsão para as próximas décadas. Não obstante, qualquer controle direto das atividades econômicas gera efeitos diretos e indiretos que necessitam ser analisados de forma pormenorizada para que o efeito líquido seja positivo.Neste sentido, este projeto justifica-se por trazer um uma análise atualizada acerca do debate, mas de forma distinta, ao buscar integrar as atividades ambientais, econômicas e sociais acerca da mitigação das mudanças climáticas de acordo com os relatórios do IPCC. Adicionalmente, a posição do Brasil no agronegócio internacional poderá ser verificada a partir das interações verificadas nos cenários elaborados.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "AVALIAÇÃO DO DESEMPENHO OPERACIONAL PARA OPERADORES DE TRANSPORTE PÚBLICO (ÔNIBUS E VANS) EM CAMPOS DOS GOYTACAZES-RJ", "description": "Este projeto tem como objetivo propor a elaboração de um modelo de avaliação do desempenho operacional das empresas de transporte público por ônibus e vans em Campos dos Goytacazes-RJ, de forma a permitir que o IMTT (Instituto Municipal de Trânsito e Transporte), responsável pela regulação do sistema de transporte público, possa controlar de forma mais efetiva as empresas que fazem parte dos consórcios que atualmente operam nas linhas municipais. O sistema de transporte público urbano do município de Campos dos Goytacazes, possui características próprias de operação (frota, linhas, tecnologias, processos, aspectos políticos etc.), sendo necessário analisar e elaborar um conjunto de indicadores que reflitam as suas singularidades e as características da demanda por viagens/deslocamentos. Devido à importância e o efeito que o transporte coletivo na qualidade de vida da população, é preciso também avaliar as suas expectativas em relação as operações. Neste sentido, este projeto propõe um conjunto de ações que irá auxiliar a gestão e regulação do sistema de transportes a saber: definição de um conjunto de indicadores de desempenho operacional e qualidade (percepção dos usuários); desenvolvimento de um sistema de BI (Business Intelligence) para agregar os diferentes dados e fornecer relatórios em tempo real sobre o desempenho dos operadores e analisar a infraestrutura de transporte públicos em Campos dos Goytacazes. Como resultado espera-se colaborar com a gestão pública municipal quanto a regulação e controle da qualidade do transporte público coletivo, composto por ônibus e vans.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "Indicadores sobre o conforto nos terminais e pontos de parada de transporte público no município: organização, segurança, tecnologia, ergonomia, comodidade, conforto para os usuários.", "description": "Esse trabalho tem como objetivo propor a realização de uma pesquisa de avaliação da qualidade dos terminais e pontos de parada de transporte coletivo, segundo a percepção dos usuários, no município de Campos dos Goytacazes-RJ. Como instrumento de coleta de dados será elaborado um questionário e aplicado nos terminais rodoviários e pontos de paradas em diferentes pontos e horários. Para análise dos dados serão utilizadas técnicas estatísticas para a tabulação e validação dos dados e, a posteriori, a apresentação dos resultados por meio de gráficos. Espera-se com esse trabalho, auxiliar os gestores públicos em identificar pontos de melhoria na qualidade dos pontos de espera e terminais rodoviários de forma a garantir o conforto e segurança necessários aos usuários.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "Liga Universitária UFF Invest", "description": "Este programa (que popularmente chamamos de projeto de extensão) visa dar continuidade às atividades desenvolvidas pelos integrantes da Liga de mercado financeiro, denominada UFFinvest, que objetiva aproximar mais os alunos do ESR e toda comunidade Campista, especialmente jovens e adultos que apresentem interesse para debater, entender, criar e aplicar o conhecimento gerado. Dessa forma, um dos principais objetivos deste programa é permitir que os discentes do ESR, principalmente os alunos do curso de ciências econômicas, ampliem os conhecimentos adquiridos durante a vivência universitária e sejam disseminadores deste conhecimento para toda a comunidade campista. Assim, o discente que participa da liga tem a oportunidade de aprofundar os estudos em uma área de conhecimento que pode o levar a trilhar uma carreira profissional em finanças. Dentre as atividades competentes à Liga, incluem-se a organização de palestra sobre os temas associados, oferecer capacitação e conhecimento sobre o mercado financeiro por meio de grupos de estudos, minicursos e demais vias de difusão de conhecimento; preparar membros e interessados para as certificações ANBIMA (CPA10, CPA20, ANCOR, por exemplo); organizar e participar de eventos e seminários e capacitar os membros para processos seletivos, de modo a criar, em linhas gerais, oportunidades para os interessados. Logo, a UFFinvest tem sido e pretende continuar a ser um instrumento que encurta a distância entre o meio acadêmico e a prática profissional, entre a academia e a comunidade de forma geral a fim de também criar uma rede de contatos com instituições locais que demanda este tipo de formação. Palavras-Chave: capacitação discentes e comunidade campista, UFFinvest, mercado financeiro, Liga Universitária Informações Relevantes para Avaliação da Proposta: A UFFINVEST foi criada no final de 2017; e, em 2018, entre outras atividades, realizou, em parceria com a empresa júnior do curso de ciências econômicas -CEC/ESR- Estratégia Júnior-, um processo seletivo para ampliação e renovação de seus membros. Atualmente a UFFINVEST é composta por 40 estudantes que estão em diferentes períodos do curso, justamente com o intuito de permitir a sustentabilidade do projeto. Além dos estudantes, a UFFINVEST é coordenada pelo professor Luiz Gustavo, e conta com a colaboração dos professores Felipe Tostes, Alan Arêdes, Rodrigo Rezende e Elizama Campos. Em 2019 os grupos de estudos fizeram atividades e em maio foi oferecido um minicurso de Excel básico para residentes do bairro Parque Imperial em uma parceria entre a liga e a Associação de Moradores (AMPI). E no fim do segundo semestre foi efetuado o processo seletivo aprovando novos trainees. Em 2020, até o momento, diante da pandemia da Covid ? 19 tivemos que inovar diante das possibilidades, como por exemplo: planejamento e execução de lives no Instagram, postagens sobre dicas de filmes, livros e podcasts sobre o mercado financeiro, criação de um grupo de estudos online para o conhecimento dos integrantes da liga sobre o mercado financeiro realizado quinzenalmente. Portanto, a UFFINVEST diminui a distância entre a academia e a prática e cria links entre alunos, comunidade campista e entidades que atua no Mercado Financeiro.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Luiz Gustavo Antônio de Souza", "institution": "ITA/Fortaleza", "title": "Apoio à incubadora de inovação - TEC Incubadora", "description": "Esta proposição tem como objetivo geral prover recursos técnicos qualificados para operação da TEC Incubadora nas áreas de marketing e comunicação.", "period": "2022 – 2025", "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Ivo Leandro Dorileo", "institution": "UFMT", "level": "Professor", "title": "BIOINSUMOS E BIOFERTILIZANTES, COM APROVEITAMENTO DE RESÍDUOS AGROPECUÁRIOS E URBANOS PARA INSUMOS, ENERGIA, BIOGÁS, BIOMETANO E AMÔNIA VERDE", "area": "Engenharia Elétrica (Potência e Telecomunicações)"}, {"person": "Jose Maria Ferreira Jardim da Silveira", "institution": "IE/UNICAMP", "level": "Professor", "title": "Orientador Eixo 4", "area": "Economia da Inovação Tecnológica"}, {"person": "Marcelo Marques de Magalhães", "institution": "FCE/UNESP", "level": "Professor", "title": "Plataforma para Avaliação de Cadeias de Suprimento de Biomassa para Biocombustíveis Avançados", "area": "Economia Agrária"}, {"person": "Mauro Donizetti Berni", "institution": "NIPE/UNICAMP", "level": "Professor", "title": "Avaliação Integrada", "area": "Planejamento Energético e Transição Energética"}, {"person": "Raphael Guarda Cavalcante", "institution": "UNIFAL", "level": "Mestrando", "title": "PRODUÇÃO DE BIOGÁS A PARTIR DE RESÍDUOS AGROPECUÁRIOS BRASILEIROS: UMA ANÁLISE ESTRATÉGICA DE POTENCIAL ENERGÉTICO E SUSTENTABILIDADE", "area": "Biotecnologia Ambiental"}, {"person": "Sonia Regina da Cal Seixas", "institution": "NIPE/UNICAMP", "level": "Professora", "title": "Artigos em colaboração nos eixos 4 e 6", "area": "Ambiente e Sociedade"}, {"person": "Stephani Cetimia Mariotti Ruiz", "institution": "IE/UNICAMP", "level": "Pós-Doc", "title": "Microdinâmica da cadeia de fornecimento de biomassa residual agrícola para produção de biocombustíveis avançados: modelagem baseada em agente", "area": "Bioeconomia e Bioenergia / Biocombustíveis"}]}]'::jsonb WHERE axis_number = 4;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Luis Alberto Follegatti Romero", "institution": "POLI/USP", "role": "Professor USP", "area": "Engenharia Química e Engenharia de Alimentos", "competency": "Domínio de Tecnologias de Purificação (Absorção, Adsorção e Extração Supercrítica)", "definition": "Alta capacidade técnica para operar e projetar sistemas que separam componentes específicos de misturas complexas, seja retendo-os em superfícies (adsorção), retendo-os em líquidos (absorção) ou usando fluidos em estados especiais (extração supercrítica).", "description": "Atuação acadêmica e científica de excelência na pós-graduação nota máxima (CAPES 7) da Escola Politécnica da USP e na coordenação de laboratório especializado (LaSPE)."}, {"person": "Luis Alberto Follegatti Romero", "institution": "POLI/USP", "role": "Coordenador do Eixo 5", "area": "Processos de Separação Térmica e Mecânica", "competency": "Modelagem Termodinâmica e Computacional", "definition": "Competência avançada para utilizar softwares e equações matemáticas para prever e simular o comportamento de fluidos e o equilíbrio de fases (como misturas líquidas e gasosas interagem), habilidade aperfeiçoada em sua especialização na Dinamarca (DTU).", "description": "Foco no desenvolvimento, otimização e aplicação de técnicas avançadas para isolar e purificar compostos em sistemas industriais."}, {"person": "Luis Alberto Follegatti Romero", "institution": "POLI/USP", "role": "Coordenador do Eixo 5", "area": "Cadeia de Biocombustíveis de Nova Geração", "competency": "Gestão de Centros de Pesquisa de Elite (LaSPE)", "definition": "Capacidade de liderar equipes, gerenciar infraestrutura laboratorial complexa e coordenar projetos de mestrado e doutorado dentro de um dos ecossistemas de engenharia mais competitivos do país (USP).", "description": "Aplicação de processos de purificação de ponta para a produção viável de combustíveis limpos, incluindo biogás, biohidrogênio, biodiesel, biogasolina e bioetanol."}, {"person": "Luis Alberto Follegatti Romero", "institution": "POLI/USP", "role": "Coordenador do Eixo 5", "area": "Termodinâmica Avançada", "competency": "Trânsito Científico Internacional e Multidisciplinar", "definition": "Bagagem cultural e acadêmica consolidada por sua atuação em três países (Peru, Portugal e Dinamarca), além de transitar com facilidade entre os fundamentos da Engenharia de Alimentos e o rigor da Engenharia Química.", "description": "Estudo do comportamento de misturas e substâncias sob diferentes condições de pressão e temperatura, visando projetar processos industriais mais eficientes."}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "role": "Professora USP", "area": "Engenharia Hidráulica, Ambiental e Sanitária", "competency": "Remoção Biológica Avançada de Nitrogênio", "definition": "Domínio técnico em investigar e aplicar rotas biológicas alternativas e eficientes para eliminar compostos de nitrogênio de águas residuárias, evitando a contaminação de corpos d''água.", "description": "Atuação acadêmica e de pesquisa (atualmente na Escola Politécnica da USP) voltada para o desenvolvimento de soluções de engenharia para o manejo de recursos hídricos e controle da poluição."}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "role": "Coordenadora Adjunta do Eixo 5", "area": "Tratamento de Águas Residuárias (Efluentes)", "competency": "Tratamento de Efluentes com Metais (Redução Biológica de Sulfato)", "definition": "Capacidade de utilizar bactérias redutoras de sulfato como estratégia biológica para imobilizar e mitigar o impacto de metais pesados tóxicos presentes em efluentes industriais ou de mineração.", "description": "Foco no projeto e na otimização de sistemas biológicos e tecnológicos para despoluir esgotos domésticos e efluentes industriais perigosos."}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "role": "Coordenadora Adjunta do Eixo 5", "area": "Valorização de Rejeitos e Economia Circular", "competency": "Recuperação de Compostos de Alto Valor Agregado", "definition": "Competência para desenhar processos biológicos que conseguem extrair e isolar substâncias valiosas a partir de efluentes e rejeitos, gerando subprodutos de interesse comercial.", "description": "Pesquisa direcionada para transformar resíduos e poluentes em matéria-prima, reinserindo substâncias na cadeia produtiva em vez de apenas descartá-las."}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "role": "Coordenadora Adjunta do Eixo 5", "area": "Planejamento em Saneamento", "competency": "Elaboração de Projetos e Planos Diretores de Saneamento", "definition": "Experiência prática e de engenharia no desenvolvimento de projetos executivos de tratamento de esgoto e na formulação de planos diretores, fundamentais para o planejamento urbano e ambiental sustentável.", "description": "Atuação na esfera macro do saneamento básico, contribuindo para a organização e diretrizes de infraestrutura de cidades e regiões."}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "role": "Coordenadora Adjunta do Eixo 5", "area": null, "competency": "Sólida Formação Acadêmica em Engenharia Hidráulica e de Saneamento", "definition": "Rigor científico e metodológico consolidado por sua formação completa em centros de excelência (graduação e doutorado na EESC-USP e docência na Poli-USP).", "description": null}]}, {"id": "projetos", "items": [{"person": "Luis Alberto Follegatti Romero", "institution": "POLI/USP", "title": "não tem CP2B no Lattes", "description": null, "period": null, "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "Produção de biometano em biorrefinarias de cana-deaçúcar a partir da integração com resíduos da pecuária", "description": "??????", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "Análise da toxicidade dos metais Fe, Cu, Ni, Zn e Co, em reatores sulfetogênicos abastecidos com diferentes doadores de elétrons.", "description": "??????", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "ratamento compacto para reuso de águas residuárias oriundas da pintura imobiliária em obras civis.", "description": "??????", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "Biolixiviação de resíduos de equipamento eletroeletrônicos em reatores contínuos.", "description": "??????", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "Produção de biometano em biorrefinarias de cana-deaçúcar a partir da integração com resíduos da pecuária", "description": "??????", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rachel Biancalana Costa", "institution": "POLI/USP", "title": "não tem CP2B no Lattes", "description": null, "period": null, "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Dave Ronel  (Hilman Ibnu Mahdi)", "institution": "USP", "level": "Doutorando", "title": "Novel Advances in CO2 and H2S removal from Biogas using Ionic liquids and Activated Carbon: Emerging trends, challenges, and prospects for sustainable applications", "area": "Engenharia Química Aplicada ao Biogás"}, {"person": "Isabela Minucio Pontes", "institution": "UNICAMP", "level": "Doutoranda", "title": "PIR e Externalidades em Arranjos de Plataformas Tecnológicas em Biorrefinaria na produção de Bioprodutos e Bioenergia de Resíduos Sólidos e Líquidos na RAC.", "area": "Arquitetura, Urbanismo Sustentável e Bioenergia"}, {"person": "Mariana Conceição da Costa", "institution": "FEQ/UNICAMP", "level": "Professora", "title": "Determinação de propriedades fisico-químicas de bioprodutos", "area": "Engenharia Química (Foco em Termodinâmica)"}, {"person": "Waldyr Luiz Ribeiro Gallo", "institution": "FEM/UNICAMP", "level": "Professor", "title": "Análise da combustão de biogás", "area": "Engenharia Mecânica com Ênfase em Termodinâmica"}]}, {"id": "infra", "items": [{"acronym": "CP2b Lab", "name": "CP2b Lab", "institution": "NIPE/UNICAMP", "lead": "Bruna de Souza Moraes", "trl": "O TRL médio desta estrutura fica concentrado entre TRL 3 e TRL 5, com o \"centro de gravidade\" no TRL 4."}]}]'::jsonb WHERE axis_number = 5;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "role": "Diretora do CP2b", "area": "Gestão e Valorização de Resíduos", "competency": null, "definition": null, "description": "Atuação direta no tratamento biológico de resíduos, transformando o que seria descartado em subprodutos de alto valor agregado (bioprodutos e bioenergia)."}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "role": "Vice-diretora do CP2b", "area": "Ciências e Engenharia Ambiental", "competency": "Liderança e Gestão de Projetos de Impacto Social", "definition": "Capacidade de idealizar, coordenar e expandir iniciativas complexas, como o projeto \"Ciência, coisa de menina\", que hoje tem alcance nacional (presente em 7 estados).", "description": "Atuação no ensino superior, pesquisa e pós-graduação voltados à sustentabilidade, saneamento e biotecnologia aplicada ao meio ambiente."}]}, {"id": "projetos", "items": [{"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Avaliação do Consórcio Microbiano de Reatores Anaeróbios Tratando Vinhaça de Cana-de-açúcar Frente A Aplicação de Diferentes Condições Operacionais Objetivando Otimizar O Rendimento da Produção de Biogás", "description": "A pesquisa visa caracterizar e avaliar o consórcio microbiano de reatores anaeróbios utilizados no tratamento de vinhaça de cana-de-açúcar, buscando compreender como diferentes condições operacionais influenciam a dinâmica microbiana e o rendimento de metano no biogás.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "title": "Ciência, coisa de menina\nCiência, coisa de menina", "description": "São inúmeros os fatores que afastam meninas e mulheres das áreas STEM, mas destacam-se a ausência do convívio com mulheres cientistas, de oportunidades de visualizar a carreira científica como um espaço para elas e entender que a universidade é a porta de entrada para a carreira científica. Em 2022, a proponente aprovou o projeto Ciência, coisa de menina: Ciência para alunas de ensino médio e ingressantes da Unifal-MG, junto a FAPEMIG. Naquele projeto, com atuação em nível municipal, Poços de Caldas - MG, a equipe realizou um programa de mentoria mensal para trabalhar a percepção que meninas do ensino médio e calouras da Unifal-MG têm da carreira científica e quando considerá-la como uma possibilidade. A equipe desse primeiro projeto, baseando-se no sucesso obtido (Instagram @cienciacoisademenina) entendeu que este edital do CNPq traz a oportunidade de levar o Ciência, coisa de menina para o Brasil, em nível nacional. Para tanto, a proponente convidou o IFAL, IFBA, UFSC e UFRGS para consolidar uma proposta com atuação em três regiões geográficas (Nordeste, Sudeste e Sul). Além do programa de mentoria, serão produtos (i) acompanhamento das egressas do programa de mentoria, (ii) realização de palestras semestrais de divulgação científica nas escolas participantes na presença de cientistas mulheres, (iii) capacitação, em território nacional, de professores da rede de ensino básico em letramento científico; (iv) promoção de formação em temas como violência de gênero, assédio, relações étnico-raciais, saúde sexual e reprodutiva; (v) realização do evento anual \"Pergunte à uma Cientista\" acoplada a grandes eventos que ocorrem anualmente nas IES participantes, e (vi) a criação do canal de divulgação (Youtube), a gravação de Podcasts e do website \"Ciência, coisa de menina\". Essa proposta visa consolidar as ações permanentes de incentivo a meninas nas áreas STEM, promover a divulgação científica em escolas e contribuir para a equidade de gênero na ciência brasileira.", "period": "2024 – atual", "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Amasa Ferreira Carvalho", "institution": "NIPE/UNICAMP", "level": "Doutora", "title": null, "area": "Ambiente, Sociedade e Emergência Climática"}, {"person": "Dante Pezzin", "institution": "USP/UNICAMP", "level": "Doutorando", "title": "Cidades Inteligentes ...e Rebeldes? Construindo alternativas ao neoliberalismo urbano com a geografia urbana crítica (Tese de Doutorado em curso)", "area": "Geografia Humana e Planejamento Urbano e Regional"}, {"person": "Mayara Régia Sousa de Melo", "institution": "UNICAMP", "level": "Doutoranda", "title": "Plano de ação climática UNICAMP", "area": "Sustentabilidade Energética e Socioambiental"}]}]'::jsonb WHERE axis_number = 6;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "role": "Diretora do CP2b", "area": "Biorrefinarias Integradas e Ecoparques", "competency": "Pesquisa Científica e Desenvolvimento Tecnológico (P&D)", "definition": "Capacidade avançada de desenvolver investigações científicas de alto nível, consolidada por sua formação (USP) e passagens por centros de excelência nacionais (LNBR) e internacionais (SDU - Dinamarca).", "description": "Desenvolvimento e estudo de sistemas industriais sustentáveis que integram múltiplos processos de conversão de biomassa, otimizando o uso de recursos e minimizando impactos ambientais."}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "role": "Diretora do CP2b", "area": "Gestão e Planejamento Acadêmico-Tecnológico", "competency": "Liderança e Gestão Interdisciplinar", "definition": "Habilidade para coordenar grandes núcleos e centros de pesquisa (como o CP2B e o NIPE/Unicamp), gerenciando equipes e projetos complexos que envolvem diferentes áreas do conhecimento.", "description": "Atuação na liderança de centros de pesquisa, coordenação de núcleos interdisciplinares, docência na pós-graduação e participação em comitês institucionais e de certificação."}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "role": "Diretora do CP2b", "area": null, "competency": "Articulação de Parcerias Estratégicas", "definition": "Competência para atuar como ponte entre a academia (universidades), o setor produtivo (indústrias) e o governo, transformando a ciência em inovação tecnológica aplicada ao mercado.", "description": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "role": "Diretora do CP2b", "area": null, "competency": "Comunicação e Disseminação Científica", "definition": "Capacidade de traduzir e debater temas complexos sobre energia e sustentabilidade para o público especializado e para a sociedade, evidenciada por sua atuação como colunista na Revista Brasil Energia.", "description": null}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "role": "Vice-diretora do CP2b", "area": "Ativismo e Direitos das Mulheres", "competency": "Gestão e Governança Institucional", "definition": "Competência para assumir cargos de liderança acadêmica e administrativa, atuando como vice-diretora de centro de pesquisa (CP2B), docente permanente de pós-graduações e fundadora de órgãos institucionais de acolhimento e defesa (GEMA/Unifal-MG).", "description": "Engajamento em conselhos municipais, políticas de combate ao assédio no ambiente universitário e ações voltadas à equidade de gênero."}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "role": "Vice-diretora do CP2b", "area": "Divulgação Científica e Incentivo a STEM", "competency": "Comunicação Pública da Ciência", "definition": "Habilidade para traduzir o conhecimento acadêmico em linguagem acessível para o grande público, evidenciada na criação e gestão do canal \"Cienplifica\" no YouTube.", "description": "Promoção e popularização da ciência para a sociedade, com foco especial em atrair meninas para as áreas de Ciências, Tecnologia, Engenharia e Matemática (STEM)."}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "role": "Vice-diretora do CP2b", "area": null, "competency": "Mentoria e Mobilização Comunitária", "definition": "Experiência prática em guiar novas gerações e articular redes de apoio a minorias na ciência, demonstrada por sua atuação voluntária em programas internacionais de mentoria e conselhos de direitos humanos.", "description": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "role": "Professora USP", "area": "Bioenergia e Biogás", "competency": "Comunicação e Difusão de Ciência Multiplataforma de biogás e bioprodutos", "definition": "Habilidade comprovada em coordenar e executar campanhas de comunicação científica utilizando diversas ferramentas modernas, como mídias sociais, gestão de sites institucionais, produção de podcasts, redação de boletins informativos e desenvolvimento de identidade visual.", "description": "Pesquisa e docência focadas na produção de combustíveis limpos e na recuperação de metano (atualmente no Departamento de Engenharia de Biossistemas da ESALQ/USP)."}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "role": "Coordenadora do Eixo 7", "area": "Engenharia Química, Ambiental e de Bioprocessos", "competency": "Operação e Otimização de Digestão Anaeróbia", "definition": "Ampla experiência prática na condução de reatores biológicos (ausência de oxigênio) aplicados à valorização de resíduos da agroindústria.", "description": "Modelagem e otimização de processos biotecnológicos industriais voltados ao tratamento de resíduos agroindustriais e à sustentabilidade."}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "role": "Coordenadora do Eixo 7", "area": "Microbiologia Industrial e Fermentação", "competency": "Análise de Biologia Molecular", "definition": "Domínio técnico para realizar a identificação molecular dos microrganismos atuantes nos processos fermentativos, garantindo maior controle e eficiência sobre a produção de metano.", "description": "Estudo e monitoramento de culturas microbianas em ambiente controlado para a conversão eficiente de biomassa."}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "role": "Coordenadora do Eixo 7", "area": "Difusão Científica e Comunicação Institucional", "competency": "Liderança e Gestão de Projetos Interdisciplinares", "definition": "Competência para assumir a governança de eixos temáticos dentro de centros de excelência (CP2B), integrando o rigor científico com estratégias de comunicação e relações públicas.", "description": "Liderança estratégica na tradução do conhecimento acadêmico sobre biogás e bioprodutos para a sociedade, atuando como coordenadora desse eixo no Centro Paulista de Estudos em Biogás e Bioprodutos (CP2B)."}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "role": "Coordenadora do Eixo 7", "area": null, "competency": "Formação Interdisciplinar e Internacional Sólida em Biotecnologia, Engenharia Química e Bioenergia", "definition": "Trajetória acadêmica de alto nível que une a Biotecnologia (UFSCar) à Engenharia Química e Bioenergia (Unicamp), com passagens e pós-doutorados de prestígio no exterior (Universidade de Birmingham - Reino Unido) e no Brasil (FEAGRI-Unicamp).", "description": null}]}, {"id": "projetos", "items": [{"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Estado-da-arte do conhecimento científico e tecnológico sobre a Digestão Anaeróbia (DA) de resíduos das usinas de cana-de-açúcar brasileiras: desafios e perspectivas", "description": null, "period": "2024 – 2025", "trl": null, "partners": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Proposta de Criação do Centro de Engenharia de Plasticultura", "description": "O objetivo do projeto é estudar, prospectar e desenvoler alternativas e soluções inteligentes para uma plasticultura contemporânea. O projeto é financiado pela empresa Braskem em parceria com a FAPESP. A equipe é composta por mais de 60 pesquisadores. A pesquisadora Bruna de Souza Moraes integra a equipe como Pesquisadora Associado. A coordenadora do projeto é Telma Teixeira Franco.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Integração do setor sucroalcooleiro e da pecuária no conceito de uma biorrefinaria produtora de metano", "description": "Os biocombustíveis derivados de fontes renováveis se tornam protagonistas em um cenário focado em aumentar a segurança energética e reduzir os impactos das mudanças climáticas. O Brasil destaca-se como maior produtor mundial de cana-de-açúcar. A vinhaça é o principal resíduo líquido do processo, sendo produzidos de 10 a 15 L de vinhaça para 1 L de etanol. Ao mesmo tempo, o país é líder mundial na pecuária bovina. Porém, a pecuária nacional apresenta baixa produtividade média, em função do manejo extensivo e baixo desenvolvimento técnico. A digestão anaeróbia (DA) da vinhaça está bem fundamentada em termos econômicos e de robustez. O potencial de produção de metano da vinhaça é estimado em 185 m de biogás para cada 1 m de etanol produzido. O principal resíduo pecuário é o estrume alinhado com rejeitos do abate, como a linha verde (lavagem gástrica do animal) e linha vermelha (processo de sangria do animal). A integração da produção de etanol com a pecuária pode melhorar o uso de terra, aumentar a produção de bioenergia e criar sinergia entre esses setores, por meio do conceito de biorrefinaria. Estudos apontam que a DA pode ser otimizada por meio da co-digestão, uma vez que um substrato único pode limitar a quantidade de biogás. No Brasil, a aplicação de sistemas de co-digestão em escala plena é pouco difundida, sendo uma janela de oportunidade o desenvolvimento de estratégias que melhorem o rendimento na produção de metano. Esta proposta pretende obter parâmetros de projeto para um sistema de co-digestão dos resíduos da produção de etanol e da pecuária, visando à produção de biogás no conceito de biorrefinaria. Biorreatores em escala de bancada serão submetidos a ensaios de potencial bioquímico de metano em sistemas de mono e co-digestão anaeróbia dos substratos vinhaça, estrume e subprodutos da pecuária. Com base nos resultados experimentais, será realizada análise de viabilidade econômica, energética e ambiental do arranjo tecnológico do processo de co-digestão.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Produção de biometano em biorrefinarias de cana-de-açúcar a partir da integração com resíduos da pecuária", "description": "utilização do biometano como fonte energética destaca-se pela crescente demanda energética alinhada à busca por tecnologias de energia limpa. O principal instrumento para se alcançar a meta de ?Carbon Neutrality? até 2050 é a transição energética. A transição energética é comumente caracterizada em 3D''s: descarbonização, descentralização e digitalização. A descarbonização inclui a substituição dos combustíveis fósseis por fontes renováveis, enquanto a descentralização foca em maior diversificação e multiplicidade de agentes geradores e distribuidores. O Brasil destaca-se como o maior produtor de cana-de-açúcar e como líder mundial na pecuária bovina, dois segmentos que resultam na produção de elevados volumes de subprodutos de baixo valor agregado e de resíduos. O país tem grande potencial a ser explorado para a produção de biogás e, consequentemente, biometano, cerca de 42,7 bilhões de m3 de biogás por ano. Entretanto, um dos desafios inerentes à produção do biometano é a purificação do biogás, principalmente com relação à presença de sulfeto e o aproveitamento energético de todos os resíduos da cadeia produtiva. Essa é a demanda de inovação trazida pela Usina Cocal, parceira desta proposta (ver anexo). Nesse sentido, este projeto propõe promover a geração descentralizada de energia na forma de biometano em biorrefinarias de cana de açúcar por meio da co-digestão anaeróbia em 2 fases (acidogênico-sulfetogênico e metanogênico) da vinhaça, resíduos lignocelulósicos da cana-de-açúcar e resíduos da pecuária com o desenvolvimento de tecnologias limpas e inovadoras para o pré-tratamento dos resíduos lignocelulósicos. Serão realizados ensaios em escala de bancada, seguido do escalonamento em planta piloto a partir da determinação de parâmetros operacionais, focados no aumento da produtividade de biometano. Com base nos resultados experimentais, será proposta a análise de viabilidade econômica, energética e ambiental do arranjo tecnológico e análise do ciclo de vida.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Bioenergia: Criação do Centro Paulista de Pesquisa em Bioenergia", "description": "Convenio para implantação do Laboratório de Bioenergia (LABIOEN), originado a partir do processo SES 073/2009 (parceria entre UNICAMP, SES e FAPESP). O LABIOEN é um complexo de voltado para desenvolvimento de projetos de PDI na área de bioenergia, incluindo laboratórios de pesquisa e espaço para escalonamento de processos (escala piloto), além de possuir um complexo de salas de aulas e de professores, auditório, sala de videoconferência e hall para eventos. Ao todo o LABIOEN compreende 6.022m2.", "period": "2021 – atual", "trl": null, "partners": null}, {"person": "Bruna de Souza Moraes", "institution": "NIPE/UNICAMP", "title": "Biometano e bioprodutos a partir de restos de alimentos: criação de um laboratório-vivo em busca da descarbonização do setor de gás natural", "description": "?????", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "title": "Ciência, coisa de menina: ciência para alunas de ensino médio e ingressantes da UNIFALMG", "description": "As meninas ainda são afastadas das ciênciasao longo de seus estudos desde os primeiros anos da escola até a universidade e são, muitas vezes, desencorajadas a seguir uma carreira como cientista. Este recorte educacional reflete-se na ausência de equidade de gênero na ciência, especialmente nas áreas STEM (termo em inglês para ciência, tencologia, engenharia e matemática). Entre os fatores que contribuem para a manutenção desse cenário desigual para meninas e mulheres na ciência, está a ausência do convívio com mulheres cientistas e de oportunidades de visualizar a carreira científica como uma espaço para elas e entender que a universidade não tem apenas papel profissionalizante, mas é a porta de entrada para a carreira científica. Nesse conxteto, insere-se este programa de mentoria para trabalhar a percepção que meninas do ensino médio e calouras do campus de Poços de Cladas da Unifal-MG têm de um carreira científica e quando considerá-la como um possibilidade. Este projeto reúne alunas do ensino médio e calouras do BICT (Bacharelado Interdisciplinar em Ciência e Tecnologia) da Unifal-MG em um programa de mentoria assistido por estudantes sêniores do BICT e da pós-graduação. Como produtos do programa, serão realizadas palestras bimestrais de divulgação científica de forma alternada nas escolas de ensino médio da cidade de Poços de Caldas para alunas e seus familiares na presença de uma cientista mulher, oficinas científicas na Unifal-MG para as participantes do programa, a construção e divulgação do mapa \"O Caminho de uma Cientista\", a realização de um evento anual \"Pergunte à uma Cientista\" no formato de uma feira de ciências na área central de Poços de Caldas, a criação do canal de divulgação (Youtube) e website \"Ciência, coisa de menina\". Essa proposta visa consolidar as ações permanentes de incentivo às alunas nas áreas STEM, promover a a divulgação científica em escolas e contribuir para a equidade de gênero na ciência.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "title": "Integração dos sistemas cana-pecuária no conceito de uma biorrefinaria produtora de metano", "description": "Os biocombustíveis derivados de fontes renováveis se tornam protagonistas em um cenário focado em aumentar a segurança energética e reduzir os impactos das mudanças climáticas. O Brasil destaca-se como maior produtor mundial de cana-de-açúcar. A vinhaça é o principal resíduo líquido do processo, sendo produzidos de 10 a 15 lde vinhaça para 1 l de etanol. Ao mesmo tempo, o país é líder mundial na pecuária bovina. Porém, a pecuária nacional apresenta baixa produtividade média, em função do manejo extensivo e baixo desenvolvimento técnico. A digestão anaeróbia (DA) da vinhaça está bem fundamentada em termos econômicos e de robustez. O potencial de produção de metano da vinhaça é estimado em 185 m³ de biogás para cada 1 m³ de etanol produzido. O principal resíduo pecuário é o estrume alinhado com rejeitos do abate, como a linha verde (lavagem gástrica do animal) e linha vermelha (processo de sangria do animal). A integração da produção de etanol com a pecuária pode melhorar o uso de terra, aumentar a produção de bioenergia e criar sinergia entre esses setores, por meio do conceito de biorrefinaria. Entretanto, a integração desses substratos em um conceito de biorrefinaria ainda demanda investigação científica. Estudos apontam que a DA pode ser otimizada por meio da co-digestão, uma vez que um substrato único pode limitar a quantidade de biogás. No Brasil, a aplicação de sistemas de co-digestão em escala plena é pouco difundida, sendo uma janela de oportunidade o desenvolvimento de estratégias que melhorem o rendimento na produção de metano. Para a consolidação dessa geração autônoma de energia, muitos estudos têm sendo desenvolvidos para otimizar e entender as rotas metabólicas da digestão anaeróbia e como controlar e estabilizar as comunidades microbianas envolvidas dentro dos processos bioquímicos que viabilizam o tratamento dos efluentes e a possibilidade de produção de biogás, entre elas o desenvolvimento de uma comunidade microbiana especializada para esses dois efluentes. Avançar em metodologias de adaptação para acelerar esse processo de estabilidade da comunidade microbiana, e por consequência, melhorar a eficiência na produção de biogás, passa a ser uma ação importante na viabilização de projetos de engenharia voltado a integração energética da indústria sucroalcooleira e pecuária. Esta proposta, portanto, pretende obter parâmetros de projeto para um sistema de co-digestão dos resíduos da produção de etanol e da pecuária, visando à produção de biogás no conceito de biorrefinaria. Biorreatores em escala de bancada serão submetidos a ensaios de potencial bioquímico de metano em sistemas de mono e co-digestão anaeróbia dos substratos vinhaça, estrume e subprodutos da pecuária. Em adição, será objetivo deste projeto desenvolver um inóculo anaeróbio adaptado à produção de metano a partir dos efluentes vinhaça e dejeto bovino, com foco no aumento da produção de biogás e aumento do conteúdo de metano. Com base nos resultados experimentais, será realizada análise de viabilidade econômica, energética e ambiental do arranjo tecnológico do processo de co-digestão.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Renata Piacentini Rodriguez", "institution": "UNIFAL/UNICAMP", "title": "Produção de biometano em biorrefinarias de cana-de-açúcar a partir da integração com resíduos da pecuária", "description": "A utilização do biometano como fonte energética destaca-se pela crescente demanda energética alinhada à busca por tecnologias de energia limpa. O principal instrumento para se alcançar a meta de ?Carbon Neutrality? até 2050 é a transição energética. A transição energética é comumente caracterizada em 3D''s: descarbonização, descentralização e digitalização. A descarbonização inclui a substituição dos combustíveis fósseis por fontes renováveis, enquanto a descentralização foca em maior diversificação e multiplicidade de agentes geradores e distribuidores. O Brasil destaca-se como o maior produtor de cana-de-açúcar e como líder mundial na pecuária bovina, dois segmentos que resultam na produção de elevados volumes de subprodutos de baixo valor agregado e de resíduos. O país tem grande potencial a ser explorado para a produção de biogás e, consequentemente, biometano, cerca de 42,7 bilhões de m3 de biogás por ano. Entretanto, um dos desafios inerentes à produção do biometano é a purificação do biogás, principalmente com relação à presença de sulfeto e o aproveitamento energético de todos os resíduos da cadeia produtiva. Essa é a demanda de inovação trazida pela Usina Cocal, parceira desta proposta (ver anexo). Nesse sentido, este projeto propõe promover a geração descentralizada de energia na forma de biometano em biorrefinarias de cana de açúcar por meio da co-digestão anaeróbia em 2 fases (acidogênico-sulfetogênico e metanogênico) da vinhaça, resíduos lignocelulósicos da cana-de-açúcar e resíduos da pecuária com o desenvolvimento de tecnologias limpas e inovadoras para o pré-tratamento dos resíduos lignocelulósicos. Serão realizados ensaios em escala de bancada, seguido do escalonamento em planta piloto a partir da determinação de parâmetros operacionais, focados no aumento da produtividade de biometano. Com base nos resultados experimentais, será proposta a análise de viabilidade econômica, energética e ambiental do arranjo tecnológico e análise do ciclo de vida.", "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "GESTÃO DE RESÍDUOS ALIMENTARES NO CAMPUS: AVALIAÇÃO, PRÉ-TRATAMENTO E POTENCIAL PARA PRODUÇÃO DE BIOGÁS", "description": null, "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "Desenvolvimento de Processo para a Produção de Biohitano a partir da Vinhaça e da Torta de Filtro gerados durante o Processo de Produção de Bioetanol da Cana de Açúcar", "description": null, "period": "2022 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "Atividade Extensionista - AEX: Do Lixo ao Luxo: Compostagem e bioEnergia nas Escolas", "description": null, "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "BIODIGESTÃO DE RESÍDUOS DA PRODUÇÃO DE BIODIESEL DE MACAÚBA PARA GERAÇÃO DE BIOGÁS", "description": null, "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "O processo de digestão anaeróbia aplicado ao tratamento de resíduos sólidos urbanos como fonte de energia e insumos químicos: uma perspectiva técnica, econômica e ambiental", "description": null, "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "A Sustainable Duo for Building Heating and Electricity Generation in Brazil", "description": null, "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "Optimizing Continuous Biohydrogen And Methane Production: Comparative Assessment Of One- And Two-stage Anaerobic Digestion Of Agave Juice For Sustainable Energy.", "description": null, "period": "2025 – 2025", "trl": null, "partners": null}, {"person": "Maria Paula Cardeal Volpi", "institution": "ESALQ/USP", "title": "não tem CP2B no Lattes", "description": null, "period": null, "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Antonio Parice Bufalo", "institution": "CP2b/UNICAMP", "level": "Graduando", "title": null, "area": "Comunicação Social e Midialogia"}, {"person": "Sofia Silva", "institution": "UNICAMP", "level": "Bolsista JC", "title": "Comunicação científica multiplataforma", "area": "Jornalismo Científico e Divulgação Científica"}]}]'::jsonb WHERE axis_number = 7;
UPDATE research_axes SET details = '[{"id": "competencias", "items": [{"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "role": "Professor UNICAMP", "area": "Política Científica, Tecnológica e de Inovação", "competency": "Liderança e Gestão em Internacionalização Universitária", "definition": "Alta competência para coordenar a diplomacia institucional e de relações internacionais de uma universidade de ponta, demonstrada em seu cargo atual e em sua atuação em comitês globais (como o Instituto Confúcio e o Grupo de Montevideo - AUGM).", "description": "Análise, formulação e avaliação de diretrizes públicas e estratégias voltadas ao avanço da ciência, tecnologia e inovação (CT&I), tanto a nível nacional quanto internacional."}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "role": "Coordenador do Eixo 8", "area": "Estudos Sociais da Ciência e da Tecnologia (CTS)", "competency": "Análise Crítica e Formulação de Políticas de CT&I", "definition": "Sólida bagagem teórica e prática (construída desde o mestrado até o doutorado na Unicamp) para mapear gargalos e propor melhorias no ecossistema de políticas de ciência e tecnologia.", "description": "Investigação interdisciplinar sobre como os avanços científicos e tecnológicos impactam e são impactados por dinâmicas sociais, culturais e econômicas."}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "role": "Coordenador do Eixo 8", "area": "Diplomacia Científica e Relações Internacionais", "competency": "Articulação Científica Global", "definition": "Forte trânsito e inserção em redes de pesquisa internacionais de elite, consolidada por passagens de pós-doutorado e intercâmbio no Reino Unido (SPRU/Universidade de Sussex) e nos EUA (Georgia Tech), além de compor corpo docente de pós-graduação no Canadá (York University).", "description": "Articulação de redes e parcerias globais para cooperação acadêmica e científica entre diferentes nações e instituições de ensino superior."}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "role": "Coordenador do Eixo 8", "area": "Inovação Social", "competency": "Pesquisa e Docência Interdisciplinar", "definition": "Capacidade de transitar com facilidade entre as ciências exatas/tecnológicas e as ciências sociais aplicadas, unindo sua base de formação em Economia para lecionar e orientar em programas multidisciplinares complexos.", "description": "Pesquisa e desenvolvimento de soluções, tecnologias e processos inovadores focados na resolução de problemas sociais e na melhoria da qualidade de vida de comunidades."}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "role": "Coordenador do Eixo 8", "area": "Gestão e Governança Acadêmica Superior", "competency": null, "definition": null, "description": "Liderança administrativa e estratégica de alto nível na tomada de decisões institucionais de grandes universidades (atualmente como Diretor Executivo na Unicamp)."}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "role": "Professora UNICAMP", "area": "Sustentabilidade e Desenvolvimento Sustentável", "competency": "Criação e Avaliação de Indicadores Participativos", "definition": "Especialidade no desenvolvimento de instrumentos metodológicos voltados ao monitoramento do desenvolvimento sustentável, com ênfase na construção de indicadores que envolvem a participação ativa da comunidade e das partes interessadas (stakeholders).", "description": "Investigação de modelos, práticas e políticas voltadas para o equilíbrio ambiental, social e econômico de longo prazo."}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Políticas Públicas Ambientais", "competency": "Monitoramento e Avaliação de Políticas Públicas", "definition": "Capacidade técnica para analisar a eficácia, os impactos e os gargalos de políticas voltadas à sustentabilidade, utilizando ferramentas de mensuração e análise científica.", "description": "Análise, estudo e proposição de diretrizes e ações governamentais ou institucionais focadas na preservação e na gestão ambiental."}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Administração e Gestão de Organizações", "competency": "Pesquisa Científica em Redes Globais", "definition": "Competência consolidada para conduzir investigações acadêmicas de alto impacto, atuando em centros de pesquisa de referência tanto no Brasil (NOSS-USP) quanto no exterior (CENSE-ULISBOA, em Portugal).", "description": "Atuação no ensino superior e na pesquisa com foco em como as organizações (públicas ou privadas) interagem com a sociedade e o meio ambiente."}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Docência e Ensino Superior Multidisciplinar em  Administração, Ciências Contábeis e Engenharia Ambiental.", "competency": "Adaptação e Mobilidade Regional no Ensino", "definition": "Capacidade de atuação e facilidade de inserção em diferentes realidades geográficas e institucionais do Brasil, evidenciada por sua experiência docente acumulada em universidades e institutos federais nas regiões Norte, Centro-Oeste, Sudeste e, atualmente, no campus da Unicamp.", "description": "Vasta experiência no magistério superior, lecionando para cursos de graduação de áreas distintas, como Administração, Ciências Contábeis e Engenharia Ambiental."}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": null, "competency": "Formação Acadêmica Híbrida (Gestão e Meio Ambiente)", "definition": "Domínio integrado de conceitos que unem a base organizacional da Administração com o rigor técnico da Engenharia Ambiental e as ciências da Sustentabilidade (USP).", "description": null}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "role": "Professora UNICAMP", "area": "Administração e Políticas Públicas", "competency": "Análise Institucional e de Políticas Públicas", "definition": "Domínio metodológico para avaliar o impacto, a implementação e a eficiência de programas governamentais e o papel das instituições públicas.", "description": "Atuação docente e de pesquisa com foco no funcionamento do Estado, análise de instituições, formulação e avaliação de políticas governamentais."}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Política Científica, Tecnológica e Inovação", "competency": "Prospecção Tecnológica e Inovação em Agricultura Digital", "definition": "Capacidade técnica para identificar tendências tecnológicas futuras e desenhar caminhos para a adoção de soluções digitais no agronegócio, competência consolidada em sua atuação na Embrapa Agricultura Digital.", "description": "Estudo de como a ciência e a tecnologia são impulsionadas por diretrizes institucionais, com ênfase na prospecção e ecossistemas de inovação."}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Transformação Digital e Agricultura", "competency": "Liderança e Gestão de Laboratórios e Centros de Pesquisa", "definition": "Habilidade de liderança para coordenar órgãos e equipes multidisciplinares complexas, demonstrada na coordenação do Laboratório de Estudos do Setor Público (LESP) e do programa de pós-graduação ICHSA na Unicamp.", "description": "Pesquisa aplicada à inserção de tecnologias digitais no campo para otimização e desenvolvimento do setor agropecuário."}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Sustentabilidade, Transição Energética e Política Urbana", "competency": "Articulação entre Academia, Governo e Setor de CT&I", "definition": "Competência para atuar na fronteira entre o conhecimento científico universitário e órgãos estratégicos de pesquisa e desenvolvimento de grande porte (como Unicamp, Embrapa e CP2B).", "description": "Investigação de dinâmicas de cidades sustentáveis e desenvolvimento regional integrado (atuando em centros especializados como o CP2B e o Semear Digital)."}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "role": "Coordenadora Adjunta do Eixo 8", "area": "Estudos sobre o Ensino Superior", "competency": "Abordagem Interdisciplinar e Multisetorial", "definition": "Sólida formação construída inteiramente em centros de excelência da Unicamp, conferindo-lhe a capacidade de cruzar as ciências humanas e sociais aplicadas com as demandas técnicas da tecnologia e da sustentabilidade.", "description": "Análise das estruturas, políticas e dinâmicas que regem as universidades e a educação de nível superior."}]}, {"id": "projetos", "items": [{"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos é dedicado ao tema \"Aproveitamento inteligente de resíduos para o desenvolvimento sustentável\" e visa criar competências com base em ciência que conduzam ao desenvolvimento e aplicações de soluções inovadoras de biogás. Os sistemas energéticos sociotécnicos que incluem soluções de biogás têm um desempenho de sustentabilidade bastante positivo uma vez que tratam resíduos, produzem combustível renovável e criam nutrientes renováveis para as plantas. No Estado de São Paulo (ESP) há muito substrato disponível - um potencial de mais de 4,5 bilhões de m3 ano de biogás - assim como uma grande demanda por seus bioprodutos, mas apenas uma fração deste potencial é aproveitada. O papel do CP2B é criar novos conhecimentos e competências que levem a soluções aplicáveis ao biogás no Estado, e articular ações conjuntas nas esferas industrial, política, social e ambiental. O CP2B tem por principal objetivo contribuir para a gestão de resíduos orgânicos e lignocelulósicos - urbanos e agroindustriais -, com prioridade para as ações voltadas à gestão pública de resíduos em setores estratégicos para a economia do estado. Em 2022, o setor sucroenergético injetou mais de R$50 bilhões na economia do estado, que responde por 50 da produção nacional de cana, por 44 do etanol e 60 de açúcar (safra 2023/24). O potencial de produção de biogás neste setor representa mais de 50 do potencial nacional, sendo que a integração com outros setores por meio de ecopólos ou ecoparques deve resultar em soluções sustentáveis e inovadoras. Nosso grupo de pesquisa tem avaliado a potencial integração de resíduos para produção de biogás. No segmento urbano, a produção de biogás a partir de RSU e esgoto sanitário representa muito mais do que uma oportunidade econômica: contribui para questões de saúde pública. Os RSU ainda são dispostos em aterros sanitários, a maioria deles sem sistema para coleta de biogás. Onde existe, a não-segregação compromete a eficiência do sistema de produção de biogás. Portanto, é necessário buscar soluções inovadoras e ações integradas da Ciência, com o poder público, com a sociedade e com o setor empresarial. Tais soluções devem ir além da geração do biogás e do digestato, inerentes aos sistemas de biogás tradicionais, abrindo um novo horizonte para pesquisas acerca do potencial de outros bioprodutos, o que permitirá agregar ainda mais valor aos resíduos. O centro irá atuar de forma transdisciplinar. O foco está em fornecer conhecimento, competência, colaboração aprofundada entre disciplinas científicas e com profissionais, novas soluções e análises da contribuição para uma transição de sustentabilidade aos stakeholders ao longo da cadeia de valor, ao setor de biogás e às comunidades em geral. Comunicação, networking, educação e capacitação são ferramentas para alcançar a visão, estratégia e objetivos do centro de concretizar o potencial de sustentabilidade e inovação das soluções de biogás. Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados: 1 - Inventário de Resíduos e Mapeamento de Tecnologias; 2 - Ciência e Tecnologia de Base; 3 - Engenharia de Processos e Bioprocessos; 4 - Avaliação Integrada Socioeconômica, Ambiental e Energética; 5 - Inovação em Bioprodutos na Cadeia do Biogás; 6 - Educação e Capacitação para o Desenvolvimento Sustentável; 7 - Difusão Científica e Comunicação; 8 - Políticas Públicas e Inovação Regulatória. Por fim, o CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "UKBrazil Climate and Sustainability Hub: Advancing Transnational Postgraduate Education for Inclusive, Interdisciplinary Collaboration in Environmental Science and Policy", "description": "The project aims to advance UK-Brazil collaboration in climate and environmental science by creating a transnational hub for research, education, and policy engagement. The project seeks to globalise postgraduate training, support emerging researchers, and foster a community of practice to inform inclusive, reciprocal models for transnational graduate education. Through shared learning and innovation, it contributes to UK-Brazil science diplomacy and the 2030 Roadmap.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "M2TIE - Meninas e Mulheres na Tecnologia: uma agenda interseccional para equidade", "description": "O projeto busca desenvolver ações para fomentar o interesse, a formação crítica, a permanência e a ascensão de meninas e mulheres nas carreiras de Ciências Exatas, Engenharias e Computação no Brasil, subsidiada por processos de apropriação tecnológica inclusiva e interseccional, de princíoios dos estudos em Ciência, Tecnologia e Sociedade (CTS) e de uma abordagem de participação comunitária. Este projeto se desenvolve em rede nacional, envolvendo pesquisadoras e pesquisadores da Universidade Tecnológica Federal do Paraná (UTFPR), da Universidade Federal da Bahia (UFBA), da Universidade de São Paulo (USP), da Universidade Estadual de Campinas (UNICAMP). Os resultados buscados são a criação de arcabouço teórico-metodológico sobre o tema; proposta de política universitária sobre equidade; conscientização sobre equidade com as comunidades envolvidas, pautadas pela crítica dos estudos em CTS; estudo comparativo entre as regiões por meio da mentoria e do acompanhamento das pessoas egressas; divulgações relacionadas por meio de produções acadêmicas abertas, recursos educacionais abertos e redes sociais.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "PHOENIX - Human Mobility, Global Challenges and Resilience in an Age of Social Stress", "description": "PHOENIX is a study of how Global Changes - including environmental and climate changes, demographic changes, changing consumption patterns, energy and land-use, developments in the politics of food and mental health, and socio-cultural transformations - impact mobility. Specifically, we undertake data modeling of social tipping points by utilizing GIS techniques and synthesizing existing geographical, earth science and longitudinal datasets. We also apply a governance of crisis approach to macro-, meso and micro-levels to understand how diverse policy areas ranging from sustainable development and disaster risk reduction to health, food, and climate change might be bridged with larger policy frameworks to understand and predict mobility patterns. The project conducts two human-centric case studies of social tipping points: (1) food security and belonging and (2) cultural survival and resilience. These case studies provide new ways of looking at how climate (im-)mobilities and their social tipping points are shaped by socio-cultural contexts and the psycho-social health of populations. Drawing on natural sciences like climate and sustainability studies and on the social sciences of political science, sociology, psychology, economics and anthropology, the project adds to the interdisciplinary diagnostic and prognostic toolbox of Global Change and mobility as well as vulnerability and resilience assessments. PHOENIX utilizes a wide evidence base - from Europe and the Middle East to Africa and South America - to ensure maximum comparative and global impact of its findings. An impact strategy is designed to reach scientific, government and public stakeholders via 1) academic workshops and publications, 2) stake-holder expert panels as well as policy briefs, and 3) Climate Mobilities and Resilience Platforms and digital art galleries, kinoeye videos and a podcast series. Phoenix examines the societal and environmental aspects of Global Change and (im-)mobilities to help leaders and the most vulnerable members of societies to understand, adapt and thrive.", "period": "2023 – 2026", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "FÊNIX - Mobilidade Humana, Desafios Globais e Resiliência em uma Era de Stress Social - Pontos de inflexão sociais e mobilidades climáticas", "description": "Essa pesquisa de pós-doutorado está vinculada ao projeto PHOENIX, que é um estudo de como as Mudanças Globais - incluindo mudanças ambientais e climáticas, mudanças demográficas, mudanças nos padrões de consumo e uso da terra, desenvolvimentos nas políticas de alimentação e saúde mental e transformações socioculturais - impactam a mobilidade humana. Especificamente, PHOENIX trabalha com modelagem de dados de pontos de inflexão sociais, utilizando Sistema de Informação Geográfica e conjuntos de dados longitudinais. Também aplica uma abordagem de governança de crise aos níveis macro, meso e micro para entender como as diversas áreas políticas que vão desde o desenvolvimento sustentável e a redução do risco de desastres até a saúde, alimentação e mudanças climáticas podem ser superadas com políticas mais amplas e com abordagens para entender e prever padrões de mobilidade. O projeto propõe ainda a realização de estudos de caso centrados no ser humano e em pontos de inflexão sociais: (1) segurança alimentar e pertencimento e (2) sobrevivência e resiliência cultural. Esses estudos de caso fornecem novas maneiras de ver como as (i)mobilidades climáticas e seus pontos de inflexão sociais são moldados pelos contextos socioculturais e pela saúde psicossocial das populações. O projeto busca contribuir para o diagnóstico e prognóstico interdisciplinar em temas ligados a mudanças globais e mobilidade, bem como avaliações de vulnerabilidade e de resiliência. O projeto está organizado em cinco clusters que se complementam. O bolsista de pós-doutorado irá atuar na interação da equipe da Unicamp com os diferentes clusters, mas desenvolverá, principalmente, as atividades referentes ao Cluster 1 (Coleta e análise de dados para modelagem de pontos de inflexão). O Cluster 1 busca gerar uma base de informações coerente, criar uma estrutura analítica comum e facilitar integração das informações geradas por meio do projeto, apoiada na construção de um banco de dados comum e de uma ferramenta de modelagem a ser desenvolvida com base em sistema de informação geográfica (GIS). Informações relacionadas e dados para fatores que influenciam a migração serão identificados e compilados. Estes incluem, dentre outros, os seguintes fatores: 1) mudanças ambientais que influenciam diretamente os meios de subsistência; 2) indicadores para governança em políticas para o desenvolvimento voltadas para questões étnico-raciais e de gênero, para fortalecimento das instituições e do Estado de direito, e para a adequada prestação de serviços públicos; 3) fatores geradores de desenvolvimento econômico; 4) fatores geradores de mudanças sociais ou culturais; 5) Uso de novas tecnologias da informação e da comunicação (TIC) que permitam que potenciais migrantes construam redes que facilitem processos migratórios; e 6) conflitos políticos causados por discórdias históricas, injustiças sociais ou desigualdades econômicas. Uma vez que a maioria destes fatores operam em diferentes níveis e escalas, é importante ter uma abordagem integrada, do local para o internacional e vice-versa. Os dados coletados permitirão à equipe do projeto caracterizar adequadamente as situações em questão, modelar relações entre os fatores de influência, formular e testar hipóteses e, finalmente, apresentar conclusões e recomendações. As principais tarefas do bolsista são: a) a elaboração de um plano para a construção do banco de dados; b) a coleta e criação de base de dados, envolvendo a compilação de dados relevantes de diferentes perspectivas disciplinares e usando ferramentas avançadas de análise multivariada, especialmente aquelas atinentes a pesquisas sobre mudanças climáticas, para abordar as relações complexas entre fatores heterogêneos e quantificar seus efeitos sobre a migração; e c) a identificação de variáveis climáticas relevantes para compreensão de fenômenos migratórios.", "period": "2023 – 2026", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Efeitos do IPCC sobre a pesquisa climática: entre Brasil e Espanha", "description": "O IPCC é responsável por definir as principais formas de inserção científica natemática das mudanças climáticas em escala mundial. O Painel em si não é umcentro de pesquisas responsável pela atuação de pesquisadores contratados.Ele possui uma forma organizacional específica que ajusta diferentesmodalidades de agentes para a produção de conhecimento climáticoreconhecido e direcionado aos governos. No presente projeto pretendemosestudar como o IPCC, enquanto uma organização transversal cruzada porinteresses executivos, empresariais e acadêmicos diferentes, vemselecionando e recrutando pesquisadores em diferentes países. Serãoestudados os casos de Brasil e Espanha entre os anos de 2000 e 2020,buscando identificar as formas de seleção e indicação de pesquisadores dosdois países, e a acumulação de capital científico advinda desse círculo depesquisadores. Através dessa análise comparativa feita por intermédio defontes documentais e entrevistas com agentes científicos e políticos dos doispaíses, espera-se compreender como sistemas científicos diferentesestabelecem suas elites na área climática e redistribuem seu capital científico.", "period": "2023 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "ENDURE: Inequalities, Community Resilience and New Governance Modalities in a Post-Pandemic World", "description": "This project will examine the short- and long-term consequences of COVID-19 from a comparative perspective. In line with the research priorities specified in the United Nations Research Roadmap, ENDURE studies the COVID-19 crisis holistically as a new source for mobilization of societies and political systems. It also examines (de-)mobilization of communities and how this has ushered in a new era of change and transformation.", "period": "2022 – 2025", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Apoio à incubação de empreendimentos solidários em Limeira, SP", "description": "O projeto busca dar continuidade às ações da Incubadora Tecnológica de Cooperativas Populares da Unicamp-Limeira (ITCP/Unicamp-Limeira), constituída a partir da obtenção de recursos obtidos por meio da Chamada MCTI/SECIS/MTE/SENAES N°89/2013. O objetivo da ITCP/Unicamp-Limeira é apoiar a constituição e o desenvolvimento de empreendimentos solidários orientados para a geração de trabalho e renda em consonância com os princípios da autogestão e do cooperativismo, por meio da interação e da troca de saberes entre a comunidade, a universidade e o poder público. Desde sua constituição, no início de 2014, a Incubadora tem atuado em diferentes projetos, a saber: (1) apoio à produção de alimentos por mulheres no Acampamento Elizabeth Teixeira; (2) realização de oficinas de confeitaria e panificação no bairro Geada, em Limeira; (3) desenvolvimento, em parceria com a Prefeitura de Limeira, de programa público de hortas urbanas para o município; (4) apoio à Cooper-L, cooperativa de catadores de Limeira; (5) acompanhamento de iniciativas visando à conformação de uma rede de trabalhadores do setor de semi-joias de Limeira. Os resultados do projeto, até o momento, são muito significativos. O apoio de novos bolsistas, nesse sentido, garantirá a continuidade das ações da Incubadora e certamente contribuirá para potencializar os efeitos positivos de suas ações.", "period": "2016 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Inovação Social e Articulação", "description": "O projeto envolve a realização de oficinas de formação sobre tecnologia social junto a entidades assistenciais e a elaboração de um banco de boas práticas em inovação social na cidade de Campinas, SP.", "period": "2015 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Estruturação da Fábrica de tijolos ecológicos e Cooperativa de prestação de serviços de construção civil da Associação Joana D?arc no Município de Campinas, SP", "description": "O projeto busca estruturar um empreendimento solidário na Associação Joana D?arc, em Campinas, gerando trabalho e renda, contribuindo com a capacitação profissional através da viabilização de oficinas de técnicas de produção de tijolos de solo-cimento, auxiliando no planejamento econômico e contábil dos empreendimentos e em sua formalização jurídica, com troca de saberes populares. Os resultados esperados compreendem a formalização tanto da Cooperativa e da Microempresa associada; alcançar resultados satisfatórios que viabilizem economicamente os empreendimentos; qualificação profissional e educação para os educandos; capacitação dos trabalhadores para manusearem as máquinas de produção de tijolo de solo-cimento; capacitação e especialização dos serviços prestados pela cooperativa; educação política; e a difusão de tecnologias alternativas de produção e construção de casas populares para comunidades de baixa renda.", "period": "2013 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Centro Público de Tecnologia Social de Campinas", "description": "O Centro Público de Tecnologia Social de Campinas, que será alocado no Centro Cultural de Inclusão e Integração Social da Unicamp (o CIS-Guanabara), terá como objetivo agregar iniciativas no campo da Tecnologia Social (TS) que atendam às necessidades tecnológicas de seu público-alvo, que são as cooperativas populares, pequenos agricultores, público do CPAT (Centro Público de Apoio ao Trabalhador de Campinas), Banco Popular da Mulher, dentre outros. O Centro desenvolverá estudos de prospecção tecnológica para o desenvolvimento de tecnologias sociais que atendam às necessidades de comunidades carentes no Município de Campinas.", "period": "2013 – atual", "trl": null, "partners": null}, {"person": "Rafael de Brito Dias", "institution": "FCA/UNICAMP", "title": "Convênio de cooperação com a Universidad Nacional de Quilmes (Argentina)", "description": "Responsável pelo acordo de cooperação bilateral entre a Universidade Estadual de Campinas e a Universidad Nacional de Quilmes (Argentina).", "period": "2013 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O CP2B, dedicado ao tema \"Aproveitamento inteligente de resíduos parao desenvolvimento sustentável\", visa criar competências com base em ciênciaque conduzam ao desenvolvimento e aplicações de soluções inovadoras debiogás.O CP2B tem como meta criar novos conhecimentos e competências quelevem a soluções aplicáveis ao biogás no Estado, contribuindo para a gestãode resíduos orgânicos e lignocelulósicos urbanos e agroindustriais , comprioridade para as ações voltadas à gestão pública de resíduos em setoresestratégicos para a economia do Estado.Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados:1 Inventário de Resíduos e Mapeamento de Tecnologias;2 Ciência e Tecnologia de Base;3 Engenharia de Processos e Bioprocessos;4 Avaliação Integrada Socioeconômica, Ambiental e Energética;5 Inovação em Bioprodutos na Cadeia do Biogás;6 Educação e Capacitação para o Desenvolvimento Sustentável;7 Difusão Científica e Comunicação;8 Políticas Públicas e Inovação Regulatória.O CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "Enfrentando desigualdades invisíveis de acesso ao saneamento básico: o caso da comunidade indígena Santa Terezinha", "description": "O modelo convencional de acompanhamento das desigualdades pode apresentar relevância em nações situadas no hemisfério norte. Entretanto, em situações de vulnerabilidade extrema, como as vivenciadas por comunidades tradicionais (ribeirinhos, quilombolas, indígenas) ou por indivíduos residentes em assentamentos informais e favelas, esse indicador encobre as variadas dificuldades que esses grupos enfrentam para assegurar o acesso a esse direito assegurado. É a partir dessa perspectiva que o projeto visa entender as diferentes maneiras de lidar com a limitação de acesso a serviços públicos relacionados ao abastecimento de água e ao tratamento de esgoto em populações que habitam contextos de discriminação, com ênfase particular nas comunidades indígenas. Ao destacar a forma como a dicotomia \"com acesso/sem acesso\" oculta sutilezas internas, o projeto visa ressaltar a variação dos níveis de mobilização e dos desafios enfrentados para a obtenção desses serviços essenciais, oferecendo subsídios para a formulação de métricas e políticas públicas mais pertinentes, com o objetivo de assegurar dignidade e justiça social a essas comunidades. O projeto está vinculado ao Programa de Incentivo a Novos Docentes da Unicamp (PIND), que faz parte da iniciativa mais ampla intitulada \"Indicadores de Desigualdade no Acesso a Serviços Públicos: Uma Abordagem para a Agenda 2030\". Este último visa desenvolver e aplicar métricas de desigualdade mais adequadas para embasar a formulação de políticas públicas alinhadas aos Objetivos de Desenvolvimento Sustentável. Além disso, instituí uma comunicação com o projeto de Ação Climática de São Vicente (2023/10280-2), na medida em que ambos os projetos progridem frente ao mesmo desafio, tanto no âmbito epistemológico quanto no político: a urgente necessidade de desenvolver novas métricas que levem em conta a diversidade de contextos vulneráveis, capazes de embasar políticas públicas equitativas. Enquanto o projeto de São Vicente desenvolve estratégias para promover a justiça climática urbana, a iniciativa indígena contribui para a equidade social e ambiental nas comunidades tradicionais. Contudo, ambos encaminham-se na mesma direção ao promover a justiça (climática, social, territorial) através de métricas inovadoras.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "Avaliação da Política Pública de Meios Contraceptivos de Longa Duração (DIU de cobre e hormonal) no município de Vinhedo-SP", "description": "O presente estudo busca analisar a eficácia e as intercorrências associadas ao uso dos dispositivos intrauterinos (DIU), tanto de cobre quanto hormonal, em cinco Unidades Básicas de Saúde (UBSs) de Vinhedo. Existe uma necessidade identificada pela ausência de uma política pública que ofereça o DIU Hormonal Mirena no Sistema Único de Saúde (SUS), que atualmente só contempla o DIU de cobre. A pesquisa, portanto, visa não apenas avaliar a eficácia dessa política, mas também fornecer subsídios para uma possível ampliação de sua aplicação. O projeto é financiado por recursos de emenda parlamentar e será conduzido em várias etapas, incluindo levantamento de literatura, análise de protocolos médicos, entrevistas, grupos focais e a elaboração de indicadores para qualificar a gestão da informação e melhorar o atendimento à população. Os resultados esperados incluem a identificação de boas práticas, a análise da elegibilidade dos usuários e a proposição de recomendações para a expansão da política, visando uma maior equidade no acesso aos métodos contraceptivos e a promoção da saúde integral da mulher.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "Indicadores de Desigualdade no Acesso a Serviços Públicos", "description": "O projeto tem como objetivo comparar e aplicar métricas de desigualdade para o acesso a serviços públicos, visando a incorporação dessas métricas no sistema de indicadores da Agenda 2030 para o desenvolvimento sustentável. Com os resultados obtidos no projeto, será instituído um Observatório de desigualdade no acesso a serviços públicos para disseminar o conhecimento produzido à toda a sociedade.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "o planejamento para justiça climática no município de São Vicente: desenvolvimento de ferramentas para tomada de decisão baseada no território com evidências científicas e comunitárias", "description": "A proposta diz respeito a uma política pública em idealização considerando o desenho da Política de Ação Climática do município de São Vicente e possui os gestores, técnicos, colaboradores da administração pública, munícipes e demais usuários dos serviços públicos e do território do município como público-alvo desta proposta. Dessa maneira, o projeto visa desenhar as Políticas Públicas de Ação Climática de São Vicente, através de evidências científicas e de forma co-criada com os atores do território. A principal característica do componente de gestão pública diz respeito à idealização de uma política pública de Ação Climática e a do componente científico diz respeito ao desenvolvimento de ferramentas para apoiar as tomadas de decisão no desenho dessa política. A elaboração de uma Política de Ação Climática que inclua a Justiça Climática possibilita que a gestão local desenvolva estruturas de governança e de capacidade de respostas aos eventos climáticos extremos, considerando a prevenção de riscos e o enfrentamento das vulnerabilidades biofísicas e sociais que potencializam a magnitude dos impactos no território.", "period": "2024 – atual", "trl": null, "partners": null}, {"person": "Natalia Molina Cetrulo", "institution": "FCA/UNICAMP", "title": "Participação social e planejamento: metodologia para elaboração, implementação e monitoramento dos Planos Municipais de Gestão Integrada de Resíduos Sólidos.", "description": "O Plano Municipal de Gestão Integrada de Resíduos Sólidos (PMGIRS) é um instrumento instituído pela Política Nacional de Resíduos Sólidos (PNRS) em 2010. De acordo com a PNRS, entre outros elementos, os Planos devem garantir ... ampla publicidade ao conteúdo dos planos [...] bem como controle social em sua formulação, implementação e operacionalização. Contudo, em muitos municípios a participação social na elaboração dos Planos é baixa, mesmo com esforços das administrações em promover processos participativos, o que impacta negativamente a cobertura da coleta seletiva. O problema aqui abordado será a baixa efetividade de processos de participação da sociedade civil (consultiva/deliberativa) na formulação, implementação e monitoramento de políticas municipais de gestão de resíduos sólidos. Neste contexto, a questão central é: Como garantir que a participação social seja potencializada na elaboração, implementação e monitoramento dos PMGIRSs? A hipótese de trabalho é que a participação pode ser potencializada a partir de uma melhor compreensão da sua lógica de funcionamento e dos instrumentos mais utilizados.Para responder aos desafios desta pesquisa, serão sistematizadas bibliografias teóricas e estudos de caso sobre participação social (teorias da democracia deliberativa) e formulação/implementação de programas de coleta seletiva. Também serão realizadas pesquisas de campo, visando elaborar um diagnóstico e prognóstico da participação social em um caso piloto de revisão do PMGIRS de Ribeirão Pires - SP. Espera-se que os resultados do projeto propiciem o desenvolvimento de uma Metodologia para ampliação da participação social no planejamento, implementação e monitoramento do PMGIRS. Descobertas teóricas, empíricas e metodológicas poderão ser replicadas em outros municípios e em outros tipos de serviços públicos.", "period": "2022 – 2025", "trl": null, "partners": null}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "title": "A incorporação dos Objetivos de Desenvolvimento Sustentável (ODS) nos instrumentos de planejamento governamental: uma análise sob a ótica do Direito à Cidade", "description": "Este projeto de pesquisa visa investigar a incorporação dos Objetivos de Desenvolvimento Sustentável (ODS) nos instrumentos de planejamento governamental, com foco nos níveis municipal e estadual, sob a ótica do Direito à Cidade. A pesquisa buscará compreender o nível de incorporação dos ODS nos documentos de planejamento, as motivações subjacentes a essa adoção, os resultados alcançados, bem como analisar a participação democrática, inclusão social e justiça espacial na gestão das cidades. Nesse sentido, serão selecionados estudos de caso para uma análise específica e situacional, permitindo uma compreensão mais aprofundada dos processos de adoção dos ODS em diferentes contextos geográficos, socioeconômicos e políticos.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "title": "Centro Paulista de Estudos em Biogás e Bioprodutos - CP2B", "description": "O Centro Paulista de Estudos em Biogás e Bioprodutos é dedicado ao tema \"Aproveitamento inteligente de resíduos para o desenvolvimento sustentável\" e visa criar competências com base em ciência que conduzam ao desenvolvimento e aplicações de soluções inovadoras de biogás. Os sistemas energéticos sociotécnicos que incluem soluções de biogás têm um desempenho de sustentabilidade bastante positivo uma vez que tratam resíduos, produzem combustível renovável e criam nutrientes renováveis para as plantas. No Estado de São Paulo (ESP) há muito substrato disponível - um potencial de mais de 4,5 bilhões de m3 ano de biogás - assim como uma grande demanda por seus bioprodutos, mas apenas uma fração deste potencial é aproveitada. O papel do CP2B é criar novos conhecimentos e competências que levem a soluções aplicáveis ao biogás no Estado, e articular ações conjuntas nas esferas industrial, política, social e ambiental. O CP2B tem por principal objetivo contribuir para a gestão de resíduos orgânicos e lignocelulósicos - urbanos e agroindustriais -, com prioridade para as ações voltadas à gestão pública de resíduos em setores estratégicos para a economia do estado. Em 2022, o setor sucroenergético injetou mais de R$50 bilhões na economia do estado, que responde por 50 da produção nacional de cana, por 44 do etanol e 60 de açúcar (safra 2023/24). O potencial de produção de biogás neste setor representa mais de 50 do potencial nacional, sendo que a integração com outros setores por meio de ecopólos ou ecoparques deve resultar em soluções sustentáveis e inovadoras. Nosso grupo de pesquisa tem avaliado a potencial integração de resíduos para produção de biogás. No segmento urbano, a produção de biogás a partir de RSU e esgoto sanitário representa muito mais do que uma oportunidade econômica: contribui para questões de saúde pública. Os RSU ainda são dispostos em aterros sanitários, a maioria deles sem sistema para coleta de biogás. Onde existe, a não-segregação compromete a eficiência do sistema de produção de biogás. Portanto, é necessário buscar soluções inovadoras e ações integradas da Ciência, com o poder público, com a sociedade e com o setor empresarial. Tais soluções devem ir além da geração do biogás e do digestato, inerentes aos sistemas de biogás tradicionais, abrindo um novo horizonte para pesquisas acerca do potencial de outros bioprodutos, o que permitirá agregar ainda mais valor aos resíduos. O centro irá atuar de forma transdisciplinar. O foco está em fornecer conhecimento, competência, colaboração aprofundada entre disciplinas científicas e com profissionais, novas soluções e análises da contribuição para uma transição de sustentabilidade aos stakeholders ao longo da cadeia de valor, ao setor de biogás e às comunidades em geral. Comunicação, networking, educação e capacitação são ferramentas para alcançar a visão, estratégia e objetivos do centro de concretizar o potencial de sustentabilidade e inovação das soluções de biogás. Para atingir suas metas, a atuação do CP2B está organizada em oito eixos temáticos integrados: 1 - Inventário de Resíduos e Mapeamento de Tecnologias; 2 - Ciência e Tecnologia de Base; 3 - Engenharia de Processos e Bioprocessos; 4 - Avaliação Integrada Socioeconômica, Ambiental e Energética; 5 - Inovação em Bioprodutos na Cadeia do Biogás; 6 - Educação e Capacitação para o Desenvolvimento Sustentável; 7 - Difusão Científica e Comunicação; 8 - Políticas Públicas e Inovação Regulatória. Por fim, o CP2B segue o conceito de laboratório vivo, com projetos que experimentam em campo novas soluções e tecnologias, aproximando pesquisadores e sociedade em uma construção coletiva.", "period": "2025 – atual", "trl": null, "partners": null}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "title": "Proposição de metodologia para geração de indicadores de inovação em agricultura digital", "description": "O conceito de inovação aberta compreende um cenário no qual o conhecimento, a experiência e ascapacidades estão dispersas entre várias organizações. As atividades inovativas podem ocorrer nas instituições de pesquisa ou fora delas, em um sistema aberto, juntando esforços e acelerando a geração de inovações. Este fenômeno também é percebido no agronegócio por meio dos ecossistemas de inovação agrícola,que envolvem vários atores incluindo organizações, universidades, governo, institutos de pesquisa, laboratórios, pequenas e grandes empresas, associações de produtores, cooperativas e os mercados financeirosnuma determinada região. No entanto, como medir ou avaliar a inovação, em especial no início do desenvolvimento de produtos de base tecnológica? Neste contexto, este projeto de pós-doutorado tem por objetivo propor uma metodologia para definir métricas e indicadores de inovação, com foco em agricultura digital, apoiando à avaliação de impacto dos Distritos Agro Tecnológicos (DATs).", "period": "2023 – 2025", "trl": null, "partners": null}, {"person": "Thais Aparecida Dibbern", "institution": "FCA/UNICAMP", "title": "Centro de Ciência para o Desenvolvimento em Agricultura Digital - CCD-AD/SemeAr", "description": "As projeções de crescimento da população mundial mostram que haverá a demanda de uma quantidade maior de alimentos, fibras e energia, impondo o aumento da produtividade agrícola, a redução de custos e o uso sustentável dos recursos naturais, visando a sua manutenção para as gerações futuras. Adicionalmente, fatores como as mudanças de hábito dos mercados consumidores, aumento da incidência de eventos climáticos extremos, além da longevidade da população urbana e a diminuição da mão de obra no meio rural são desafios ainda não superados. Desta forma, é fundamental considerar o processo de transformação digital no campo, com a inclusão cada vez maior de equipamentos e sensores, que coletam e geram dados com um volume significativo, da ordem de terabytes de informação, superando a capacidade humana de processamento. A diversidade de dados que podem ser utilizados em todos os elos da cadeia produtiva desde a pré-produção, produção (dentro da porteira) e na pós-produção, e as diversas escalas em que se encontram são desafios de pesquisa relevantes para a Ciência da Computação, que pode contribuir com soluções inovadoras, por meio da adoção de técnicas, métodos e algoritmos computacionais para manipular e compreender o inter-relacionamento destes dados de forma mais adequada, rápida e eficiente, dando subsídios aos agricultores para uma melhor tomada de decisão no campo. Entretanto, para que o Brasil seja capaz de garantir e ampliar sua posição de destaque nos mercados sustentáveis de alimentos, fibras e bioenergia, atendendo às crescentes demandas nacional e internacional por segurança alimentar, nutricional, socioambiental e climática, torna-se imprescindível superar as desigualdades no campo a partir de pesquisas, desenvolvimentos, inovações (PDI) e de uma melhor difusão entre pequenos e médios produtores de tecnologias associadas à agricultura digital. Algumas dessas tecnologias inovadoras apontadas como críticas da transformação digital da agricultura são: computação em borda/nuvem, internet das coisas (IoT), mídias e redes sociais, big data, ciência de dados, inteligência artificial, realidade aumentada, robótica, conectividade ubíqua, aprendizado de máquina, gêmeos digitais, automação, biotecnologia e bioinformática, além da nanotecnologia. Nessa perspectiva, a PDI associada ao uso das tecnologias digitais visando os pequenos e médios produtores se justifica por trazer oportunidades para a agricultura brasileira de modo a: - Inserir estes produtores no processo de transformação digital em curso, considerando a diversidade regional produtiva e de recursos naturais; - Promover o aumento da conectividade de dispositivos eletrônicos no campo, visando reduzir custos de implementação de ativos tecnológicos digitais; - Conectar múltiplos atores de cadeias produtivas, de modo a reduzir custos de transação; - Integrar tecnologias digitais nos processos produtivos rurais de forma efetiva e simples, visando gerar impactos socioeconômicos nos curto e médio prazos; - Promover a capacitação tecnológica e o compartilhamento de conhecimento e de práticas, visando acelerar a adoção de ativos tecnológicos digitais pelos mercados; - Possibilitar novos modelos de negócios e operações no processo de transformação digital no campo, visando obter investimentos para a escalabilidade. - Induzir e fortalecer modelos de intensificação sustentável por meio de sistemas integrados de produção, visando ganhos de eficiência e produtividade agropecuária. Neste contexto, o CCD-AD/SemeAR proposto tem como missão atuar em pesquisa, desenvolvimento e inovação em tecnologias emergentes visando, principalmente, à inclusão digital de pequenos e médios produtores rurais.", "period": "2023 – atual", "trl": null, "partners": null}]}, {"id": "equipe", "items": [{"person": "Sergio Valdir Bajay", "institution": "NIPE/UNICAMP", "level": "Professor", "title": null, "area": "Planejamento Energético"}]}]'::jsonb WHERE axis_number = 8;
